css:
@property --dmp-pulse-share { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --dmp-pulse-fade { syntax: "<length>"; inherits: false; initial-value: 0px; }

.dmp-pulse {
  /* re-theme with these four */
  --dmp-pulse-bg: oklch(0.175 0.009 60);
  --dmp-pulse-ink: oklch(0.955 0.012 85);
  --dmp-pulse-live: oklch(0.665 0.215 27);
  --dmp-pulse-up: oklch(0.83 0.14 158);

  --dmp-pulse-panel: color-mix(in oklch, var(--dmp-pulse-bg) 95%, var(--dmp-pulse-ink));
  --dmp-pulse-raise: color-mix(in oklch, var(--dmp-pulse-bg) 88%, var(--dmp-pulse-ink));
  --dmp-pulse-line: color-mix(in oklch, var(--dmp-pulse-ink) 11%, transparent);
  --dmp-pulse-hair: color-mix(in oklch, var(--dmp-pulse-ink) 6%, transparent);
  --dmp-pulse-mute: color-mix(in oklch, var(--dmp-pulse-ink) 64%, var(--dmp-pulse-bg));
  --dmp-pulse-faint: color-mix(in oklch, var(--dmp-pulse-ink) 42%, var(--dmp-pulse-bg));
  --dmp-pulse-down: color-mix(in oklch, var(--dmp-pulse-live) 70%, var(--dmp-pulse-ink));
  --dmp-pulse-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dmp-pulse-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dmp-pulse-out: cubic-bezier(.16, 1, .3, 1);
  --dmp-pulse-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.089 24.3%, 1.09 28.6%, 1.064 32.1%, .996 41.7%, .983 46.5%, .987 54.1%, 1.001 66.5%, 1);

  width: 100%;
  height: var(--dmp-pulse-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dmp-pulse-bg);
  color: var(--dmp-pulse-ink);
  font: 13px/1.45 var(--dmp-pulse-sans);
  accent-color: var(--dmp-pulse-live);
  color-scheme: dark;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dmp-pulse-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ol, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--dmp-pulse-live); outline-offset: 2px; border-radius: 8px; }
  & [hidden] { display: none !important; }
  & [data-sec="city"] { --sec: oklch(0.82 0.12 78); }
  & [data-sec="politics"] { --sec: oklch(0.74 0.14 22); }
  & [data-sec="climate"] { --sec: oklch(0.8 0.13 152); }
  & [data-sec="business"] { --sec: oklch(0.76 0.09 235); }
  & [data-sec="culture"] { --sec: oklch(0.77 0.12 330); }
  & [data-sec="sport"] { --sec: oklch(0.86 0.14 108); }
}
.dmp-pulse__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dmp-pulse__shell { height: 100%; display: grid; grid-template-columns: 76px minmax(0, 1fr); }

/* ---------- rail */
.dmp-pulse__rail {
  display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 18px 0;
  border-right: 1px solid var(--dmp-pulse-line);
  background: color-mix(in oklch, var(--dmp-pulse-bg) 80%, black);
}
.dmp-pulse__mark {
  width: 38px; height: 38px; display: grid; place-items: center; border-radius: 11px; background: var(--dmp-pulse-live); color: var(--dmp-pulse-bg);
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
}
.dmp-pulse__navlist {
  display: grid; gap: 6px;
  & button {
    position: relative; width: 56px; padding: 9px 0 7px; display: grid; justify-items: center; gap: 4px; border-radius: 12px;
    color: var(--dmp-pulse-faint); font-size: 10px; font-weight: 650; letter-spacing: .04em;
    transition: background-color .2s, color .2s;
    &::before { content: ""; position: absolute; left: -10px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dmp-pulse-live); scale: 1 0; transition: scale .35s var(--dmp-pulse-out); }
    &:hover { color: var(--dmp-pulse-ink); background: var(--dmp-pulse-hair); }
    &[aria-current="page"] { color: var(--dmp-pulse-ink); background: var(--dmp-pulse-raise); &::before { scale: 1 1; } }
  }
}

/* ---------- main + head */
.dmp-pulse__main { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 14px; padding: 16px 18px 18px; }
.dmp-pulse__head { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px 26px; }
.dmp-pulse__eyebrow {
  display: flex; align-items: center; gap: 7px; font: 600 10.5px/1 var(--dmp-pulse-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-pulse-live);
  & time { color: var(--dmp-pulse-mute); font-variant-numeric: tabular-nums; }
}
.dmp-pulse__dot {
  position: relative; width: 8px; height: 8px; border-radius: 50%; background: var(--dmp-pulse-live);
  &::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: inherit; animation: dmp-pulse-ping 1.6s cubic-bezier(.2, .6, .35, 1) infinite; }
}
.dmp-pulse:has([data-pause][aria-pressed="true"]) {
  & .dmp-pulse__dot { background: var(--dmp-pulse-faint); &::after { animation: none; opacity: 0; } }
  & .dmp-pulse__eyebrow { color: var(--dmp-pulse-mute); }
}
.dmp-pulse__title h2 { margin-top: 7px; font-size: clamp(15px, 1.6cqi, 18px); font-weight: 600; letter-spacing: -.01em; color: var(--dmp-pulse-mute); text-wrap: balance; }
.dmp-pulse__big {
  display: flex; align-items: baseline; gap: 12px;
  & output { font-size: clamp(34px, 4.6cqi, 52px); font-weight: 760; letter-spacing: -.045em; line-height: .9; font-variant-numeric: tabular-nums; }
}
.dmp-pulse__chg {
  font: 600 12px var(--dmp-pulse-mono); font-variant-numeric: tabular-nums; color: var(--dmp-pulse-up); white-space: nowrap;
  &.dn { color: var(--dmp-pulse-down); }
}
.dmp-pulse__ctrls { margin-left: auto; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.dmp-pulse__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dmp-pulse-hair); box-shadow: inset 0 0 0 1px var(--dmp-pulse-line);
  & button { padding: 5px 11px; border-radius: 7px; font: 600 11.5px var(--dmp-pulse-mono); color: var(--dmp-pulse-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dmp-pulse-ink); }
  & button[aria-checked="true"] { background: var(--dmp-pulse-ink); color: var(--dmp-pulse-bg); }
}
.dmp-pulse__pause {
  display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px 6px 10px; border-radius: 10px; font-weight: 650; font-size: 12.5px;
  box-shadow: inset 0 0 0 1px var(--dmp-pulse-line); transition: background-color .2s, box-shadow .2s;
  & .r { display: none; fill: currentColor; stroke: none; }
  &:hover { background: var(--dmp-pulse-hair); }
  &[aria-pressed="true"] { background: var(--dmp-pulse-live); color: var(--dmp-pulse-bg); box-shadow: none; & .p { display: none; } & .r { display: block; } }
}

/* ---------- views + panels */
.dmp-pulse__view { min-height: 0; }
.dmp-pulse__live {
  display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1.62fr) minmax(290px, 1fr);
  grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "chart rank" "detail rank";
}
.dmp-pulse__panel {
  position: relative; min-width: 0; min-height: 0; border-radius: 14px; background: var(--dmp-pulse-panel);
  box-shadow: inset 0 0 0 1px var(--dmp-pulse-line);
  animation: dmp-pulse-rise .7s var(--dmp-pulse-out) both; animation-delay: calc(var(--i, 0) * 70ms);
}
.dmp-pulse__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap;
  & h3 { font-size: 11px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--dmp-pulse-mute); }
}
.dmp-pulse__count { font-size: 11.5px; color: var(--dmp-pulse-faint); font-variant-numeric: tabular-nums; }

/* chart */
.dmp-pulse__chart { grid-area: chart; display: flex; flex-direction: column; gap: 8px; padding: 12px 14px 8px; }
.dmp-pulse__legend {
  display: flex; gap: 14px; font-size: 11.5px; color: var(--dmp-pulse-mute);
  & li { display: flex; align-items: center; gap: 6px; min-width: 0; }
  & span { max-width: 26ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & i { width: 10px; height: 10px; border-radius: 3px; flex: none; }
  & .k-story { background: var(--dmp-pulse-live); }
  & .k-rest { background: color-mix(in oklch, var(--dmp-pulse-ink) 30%, transparent); }
}
.dmp-pulse__plot { position: relative; flex: 1; min-height: 0; cursor: crosshair; }
.dmp-pulse__plot canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.dmp-pulse__tip {
  position: absolute; left: 0; top: 0; z-index: 3; min-width: 168px; padding: 9px 11px; border-radius: 10px; pointer-events: none;
  background: color-mix(in oklch, var(--dmp-pulse-bg) 70%, black); box-shadow: inset 0 0 0 1px var(--dmp-pulse-line), 0 14px 30px -12px black;
  font-size: 12px; opacity: 0; transition: opacity .15s;
  & time { display: block; margin-bottom: 4px; font: 600 10.5px var(--dmp-pulse-mono); letter-spacing: .08em; color: var(--dmp-pulse-faint); }
  & p { display: flex; justify-content: space-between; gap: 16px; color: var(--dmp-pulse-mute); }
  & b { color: var(--dmp-pulse-ink); font-variant-numeric: tabular-nums; }
  & .s b { color: var(--dmp-pulse-live); }
  &.on { opacity: 1; }
}

/* ranked list */
.dmp-pulse__rank { grid-area: rank; display: flex; flex-direction: column; gap: 10px; padding: 12px 8px 8px 12px; }
.dmp-pulse__rank > .dmp-pulse__ph { padding-right: 6px; }
.dmp-pulse__chips {
  display: flex; flex-wrap: wrap; gap: 5px; padding: 2px 4px 2px 0;
  & button {
    flex: none; padding: 4px 10px; border-radius: 99px; font-size: 11.5px; font-weight: 600; color: var(--dmp-pulse-mute);
    box-shadow: inset 0 0 0 1px var(--dmp-pulse-line); transition: background-color .2s, color .2s, box-shadow .2s;
    &[data-sec]:not([data-sec="all"])::before { content: ""; display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--sec); vertical-align: 1px; }
    &:hover { color: var(--dmp-pulse-ink); background: var(--dmp-pulse-hair); }
    &[aria-checked="true"] { background: var(--dmp-pulse-ink); color: var(--dmp-pulse-bg); box-shadow: none; }
  }
}
.dmp-pulse__list {
  --dmp-pulse-fade: 0px;
  flex: 1; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 2px; padding: 0 4px 4px 0;
  mask-image: linear-gradient(to bottom, transparent 0, #000 var(--dmp-pulse-fade), #000 calc(100% - 14px), transparent);
}
@supports (animation-timeline: scroll()) {
  .dmp-pulse__list { animation: dmp-pulse-fadetop linear both; animation-timeline: scroll(self); animation-range: 0 48px; }
}
.dmp-pulse__list.enter .dmp-pulse__row { animation: dmp-pulse-rise .55s var(--dmp-pulse-out) both; animation-delay: calc(var(--i, 0) * 38ms + 160ms); }
.dmp-pulse__row {
  --sec: var(--dmp-pulse-ink);
  position: relative; display: grid; grid-template-columns: 20px minmax(0, 1fr) 56px 64px; align-items: center; gap: 10px;
  padding: 8px 8px 8px 6px; border-radius: 10px; cursor: pointer; outline-offset: -2px;
  transition: background-color .2s;
  &:hover { background: var(--dmp-pulse-hair); }
  &[aria-selected="true"] { background: var(--dmp-pulse-raise); box-shadow: inset 2px 0 0 var(--dmp-pulse-live); }
  & .rk { font: 600 11px var(--dmp-pulse-mono); color: var(--dmp-pulse-faint); text-align: right; font-variant-numeric: tabular-nums; }
  & .tx { min-width: 0; display: grid; gap: 2px; }
  & .tx b { font-weight: 600; font-size: 12.5px; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-wrap: pretty; }
  & .tx small { font-size: 11px; color: var(--dmp-pulse-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .tx small i { font-style: normal; font-weight: 700; font-size: 9.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--sec); margin-right: 5px; }
  & .tx small em { font-style: normal; color: var(--dmp-pulse-live); font-weight: 700; margin-left: 5px; }
  & .sp { width: 56px; height: 22px; overflow: visible; }
  & .sp .l { fill: none; stroke: var(--sec); stroke-width: 1.5; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
  & .sp .a { fill: color-mix(in oklch, var(--sec) 16%, transparent); }
  & .nm { display: grid; justify-items: end; gap: 1px; font-variant-numeric: tabular-nums; }
  & .nm b { font-size: 14px; font-weight: 720; letter-spacing: -.02em; }
  & .nm small { font: 600 10.5px var(--dmp-pulse-mono); color: var(--dmp-pulse-up); }
  & .nm small.dn { color: var(--dmp-pulse-down); }
  &.hot .rk::before { content: ""; position: absolute; left: 4px; top: 50%; width: 5px; height: 5px; margin-top: -2.5px; border-radius: 50%; background: var(--dmp-pulse-up); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dmp-pulse-up) 25%, transparent); }
}

/* detail */
.dmp-pulse__detail {
  grid-area: detail; overflow: auto; max-height: 330px; padding: 14px 16px;
  display: grid; gap: 12px 22px; align-content: start;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  grid-template-areas: "head stats" "depth refs";
  & h4 { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-pulse-faint); margin-bottom: 8px; }
}
.dmp-pulse__dhead {
  grid-area: head; min-width: 0;
  & h3 { margin-top: 4px; font-size: clamp(15px, 1.55cqi, 18px); font-weight: 700; letter-spacing: -.015em; line-height: 1.22; text-wrap: balance; }
}
.dmp-pulse__dsec { --sec: var(--dmp-pulse-ink); font-size: 10px; font-weight: 750; letter-spacing: .13em; text-transform: uppercase; color: var(--sec); }
.dmp-pulse__dmeta { margin-top: 6px; font-size: 12px; color: var(--dmp-pulse-mute); text-wrap: pretty; }
.dmp-pulse__dacts { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.dmp-pulse__btn {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px 6px 9px; border-radius: 9px; font-size: 12px; font-weight: 650;
  background: var(--dmp-pulse-ink); color: var(--dmp-pulse-bg); transition: background-color .2s, color .2s, box-shadow .2s, scale .2s var(--dmp-pulse-out);
  & .dmp-pulse__ic { width: 15px; height: 15px; }
  &:active { scale: .97; }
  &.ghost { background: none; color: var(--dmp-pulse-ink); box-shadow: inset 0 0 0 1px var(--dmp-pulse-line); &:hover { background: var(--dmp-pulse-hair); } }
  &[aria-pressed="true"] { background: var(--dmp-pulse-live); color: var(--dmp-pulse-bg); }
}
.dmp-pulse__stats {
  grid-area: stats; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 14px; align-content: start;
  & div { min-width: 0; padding: 8px 10px; border-radius: 10px; background: var(--dmp-pulse-hair); }
  & dt { font-size: 10.5px; color: var(--dmp-pulse-faint); letter-spacing: .02em; }
  & dd { margin-top: 2px; font-size: 18px; font-weight: 720; letter-spacing: -.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { font-size: 11px; font-weight: 600; color: var(--dmp-pulse-mute); letter-spacing: 0; margin-left: 3px; }
  & .share { display: flex; align-items: center; gap: 10px; }
  & .ring {
    --dmp-pulse-share: 0; width: 30px; height: 30px; flex: none; border-radius: 50%;
    background: conic-gradient(var(--dmp-pulse-live) calc(var(--dmp-pulse-share) * 1%), color-mix(in oklch, var(--dmp-pulse-ink) 12%, transparent) 0);
    mask: radial-gradient(circle, transparent 54%, #000 56%);
    transition: --dmp-pulse-share .9s var(--dmp-pulse-out);
  }
}
.dmp-pulse__depth {
  grid-area: depth; min-width: 0;
  & .b { display: grid; grid-template-columns: 34px minmax(0, 1fr) 38px; align-items: center; gap: 8px; font-size: 11.5px; margin-top: 5px; }
  & .b span { font-family: var(--dmp-pulse-mono); color: var(--dmp-pulse-faint); font-size: 10.5px; }
  & .b i { height: 7px; border-radius: 4px; background: var(--dmp-pulse-hair); overflow: hidden; }
  & .b i::after { content: ""; display: block; height: 100%; width: calc(var(--v) * 1%); border-radius: 4px; background: color-mix(in oklch, var(--dmp-pulse-ink) 72%, transparent); transform-origin: left; animation: dmp-pulse-grow .8s var(--dmp-pulse-out) both; animation-delay: calc(var(--i, 0) * 60ms); }
  & .b b { text-align: right; font-variant-numeric: tabular-nums; font-weight: 650; }
}
.dmp-pulse__refs { grid-area: refs; min-width: 0; & ul { display: grid; gap: 1px; margin-top: 8px; } }
.dmp-pulse__rbar {
  display: flex; height: 8px; border-radius: 4px; overflow: hidden; gap: 2px;
  & i { flex: var(--v) 1 0; min-width: 2px; background: var(--c); transition: flex-grow .7s var(--dmp-pulse-out); }
  &.big { height: 14px; border-radius: 6px; margin: 12px 0 16px; }
}
.dmp-pulse__refs li { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto 40px; align-items: center; gap: 8px; font-size: 11.5px; color: var(--dmp-pulse-mute); }
.dmp-pulse__refs li i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
.dmp-pulse__refs li b { color: var(--dmp-pulse-ink); font-variant-numeric: tabular-nums; font-weight: 650; }
.dmp-pulse__refs li span:last-child { text-align: right; font-family: var(--dmp-pulse-mono); font-size: 10.5px; color: var(--dmp-pulse-faint); }

/* sections view */
.dmp-pulse__secs, .dmp-pulse__srcs { display: grid; }
.dmp-pulse__secs > .dmp-pulse__panel, .dmp-pulse__srcs > .dmp-pulse__panel { overflow: auto; padding: 14px 16px; }
.dmp-pulse__mix { display: flex; height: 26px; gap: 3px; margin: 14px 0 10px; }
.dmp-pulse__mix i { flex: var(--v) 1 0; border-radius: 6px; background: var(--sec); transition: flex-grow .7s var(--dmp-pulse-out); }
.dmp-pulse__mix i.o { background: color-mix(in oklch, var(--dmp-pulse-ink) 18%, transparent); }
.dmp-pulse__seclist { display: grid; gap: 2px; }
.dmp-pulse__secrow {
  width: 100%; display: grid; grid-template-columns: 110px minmax(0, 1fr) 150px 76px 54px minmax(0, 1.3fr) 18px; align-items: center; gap: 14px;
  padding: 12px 10px; border-radius: 10px; transition: background-color .2s;
  animation: dmp-pulse-rise .5s var(--dmp-pulse-out) both; animation-delay: calc(var(--i, 0) * 45ms);
  &:hover { background: var(--dmp-pulse-hair); & .go { opacity: 1; translate: 0 0; } }
  & .nm { display: flex; align-items: center; gap: 8px; font-weight: 650; }
  & .nm::before { content: ""; width: 9px; height: 9px; border-radius: 3px; background: var(--sec); }
  & .bar { height: 10px; border-radius: 5px; background: var(--dmp-pulse-hair); overflow: hidden; }
  & .bar i { display: block; height: 100%; width: calc(var(--v) * 1%); border-radius: 5px; background: var(--sec); transition: width .7s var(--dmp-pulse-out); }
  & .v { text-align: right; font-weight: 720; font-size: 14px; font-variant-numeric: tabular-nums; }
  & .tr { width: 150px; height: 30px; overflow: visible; }
  & .tr .l { fill: none; stroke: var(--sec); stroke-width: 1.5; vector-effect: non-scaling-stroke; stroke-linejoin: round; }
  & .tr .a { fill: color-mix(in oklch, var(--sec) 14%, transparent); }
  & .p { text-align: right; font: 600 11px var(--dmp-pulse-mono); color: var(--dmp-pulse-mute); }
  & .top { min-width: 0; font-size: 12px; color: var(--dmp-pulse-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .top small { color: var(--dmp-pulse-faint); margin-right: 5px; font-size: 10.5px; }
  & .go { opacity: 0; translate: -4px 0; transition: opacity .2s, translate .3s var(--dmp-pulse-out); color: var(--dmp-pulse-mute); }
}
.dmp-pulse__foot { margin-top: 12px; padding: 10px 10px 0; border-top: 1px solid var(--dmp-pulse-line); font-size: 12px; color: var(--dmp-pulse-faint); font-variant-numeric: tabular-nums; text-wrap: pretty; }

/* sources view */
.dmp-pulse__cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 10px; }
.dmp-pulse__card {
  padding: 12px 14px; border-radius: 12px; background: var(--dmp-pulse-hair); box-shadow: inset 3px 0 0 var(--c);
  animation: dmp-pulse-rise .5s var(--dmp-pulse-out) both; animation-delay: calc(var(--i, 0) * 50ms);
  & h4 { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dmp-pulse-mute); }
  & .v { margin-top: 6px; display: flex; align-items: baseline; gap: 8px; }
