.dmp-paywall {
  /* re-theme with these four */
  --dmp-paywall-bg: oklch(0.973 0.012 85);
  --dmp-paywall-ink: oklch(0.25 0.022 50);
  --dmp-paywall-accent: oklch(0.49 0.155 25);
  --dmp-paywall-good: oklch(0.55 0.12 156);

  --dmp-paywall-card: color-mix(in oklch, var(--dmp-paywall-bg) 40%, white);
  --dmp-paywall-side: color-mix(in oklch, var(--dmp-paywall-bg) 93%, var(--dmp-paywall-ink));
  --dmp-paywall-line: color-mix(in oklch, var(--dmp-paywall-ink) 13%, transparent);
  --dmp-paywall-hair: color-mix(in oklch, var(--dmp-paywall-ink) 7%, transparent);
  --dmp-paywall-soft: color-mix(in oklch, var(--dmp-paywall-ink) 5%, transparent);
  --dmp-paywall-mute: color-mix(in oklch, var(--dmp-paywall-ink) 66%, var(--dmp-paywall-bg));
  --dmp-paywall-faint: color-mix(in oklch, var(--dmp-paywall-ink) 45%, var(--dmp-paywall-bg));
  --dmp-paywall-tint: color-mix(in oklch, var(--dmp-paywall-accent) 10%, var(--dmp-paywall-card));
  --dmp-paywall-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --dmp-paywall-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dmp-paywall-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dmp-paywall-out: cubic-bezier(.16, 1, .3, 1);
  --dmp-paywall-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);

  width: 100%;
  height: var(--dmp-paywall-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dmp-paywall-bg);
  color: var(--dmp-paywall-ink);
  font: 13px/1.45 var(--dmp-paywall-sans);
  accent-color: var(--dmp-paywall-accent);
  color-scheme: light;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dmp-paywall-ink) 22%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dmp-paywall-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dmp-paywall-accent); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
  & [data-k="search"] { --c: oklch(0.58 0.085 245); }
  & [data-k="social"] { --c: oklch(0.74 0.125 72); }
  & [data-k="newsletter"] { --c: var(--dmp-paywall-accent); }
  & [data-k="direct"] { --c: oklch(0.64 0.07 182); }
  & [data-k="monthly"] { --c: color-mix(in oklch, var(--dmp-paywall-ink) 72%, var(--dmp-paywall-bg)); }
  & [data-k="annual"] { --c: var(--dmp-paywall-accent); }
  & [data-k="student"] { --c: oklch(0.74 0.125 72); }
  & [data-k="gift"] { --c: oklch(0.58 0.085 245); }
}
.dmp-paywall__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dmp-paywall__cap { font-size: 10.5px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--dmp-paywall-faint); }

.dmp-paywall__shell { height: 100%; display: grid; grid-template-columns: 212px minmax(0, 1fr); }

/* ---------- side */
.dmp-paywall__side { display: flex; flex-direction: column; gap: 6px; min-height: 0; padding: 20px 14px 16px; background: var(--dmp-paywall-side); border-right: 1px solid var(--dmp-paywall-line); }
.dmp-paywall__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px;
  & b { display: block; font: 700 15.5px/1.15 var(--dmp-paywall-serif); letter-spacing: -.01em; }
  & small { display: block; font-size: 11px; color: var(--dmp-paywall-mute); }
}
.dmp-paywall__logo { width: 32px; height: 32px; flex: none; display: grid; place-items: center; border-radius: 9px; background: var(--dmp-paywall-accent); color: var(--dmp-paywall-bg); font: 700 italic 19px/1 var(--dmp-paywall-serif); }
.dmp-paywall__nav {
  display: grid; gap: 2px;
  & button {
    display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; color: var(--dmp-paywall-mute); font-weight: 560;
    transition: background-color .2s, color .2s;
    &:hover { background: var(--dmp-paywall-soft); color: var(--dmp-paywall-ink); }
    &[aria-current="page"] { background: var(--dmp-paywall-card); color: var(--dmp-paywall-ink); font-weight: 660; box-shadow: 0 1px 0 var(--dmp-paywall-line), 0 8px 18px -12px color-mix(in oklch, var(--dmp-paywall-ink) 40%, transparent); & .dmp-paywall__ic { color: var(--dmp-paywall-accent); } }
  }
}
.dmp-paywall__testcard {
  margin-top: auto; display: grid; gap: 6px; padding: 14px 10px 4px; border-top: 1px solid var(--dmp-paywall-line);
  & b { font-size: 12.5px; }
  & small { font-size: 11px; color: var(--dmp-paywall-mute); font-variant-numeric: tabular-nums; }
}
.dmp-paywall__prog { height: 6px; border-radius: 3px; background: var(--dmp-paywall-hair); overflow: hidden; & i { display: block; height: 100%; width: calc(var(--p) * 1%); border-radius: 3px; background: var(--dmp-paywall-accent); transform-origin: left; animation: dmp-paywall-grow 1.1s var(--dmp-paywall-out) .3s both; } }

/* ---------- main */
.dmp-paywall__main { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 14px; padding: 18px 20px; }
.dmp-paywall__head {
  display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 18px;
  & h2 { margin-top: 4px; font: 700 clamp(20px, 2.4cqi, 27px)/1.1 var(--dmp-paywall-serif); letter-spacing: -.02em; text-wrap: balance; }
}
.dmp-paywall__ctrls { display: flex; flex-wrap: wrap; gap: 8px; }
.dmp-paywall__seg {
  display: inline-flex; align-items: center; flex-wrap: wrap; padding: 3px; border-radius: 10px; background: var(--dmp-paywall-soft); box-shadow: inset 0 0 0 1px var(--dmp-paywall-line);
  & button { padding: 5px 11px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dmp-paywall-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dmp-paywall-ink); }
  & button[aria-checked="true"] { background: var(--dmp-paywall-card); color: var(--dmp-paywall-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dmp-paywall-ink) 20%, transparent), 0 0 0 1px var(--dmp-paywall-line); }
  &.sm button { padding: 4px 9px; font-size: 11.5px; }
}
.dmp-paywall__seglbl { padding: 0 6px 0 8px; font-size: 11px; color: var(--dmp-paywall-faint); }
.dmp-paywall__view { min-height: 0; }
.dmp-paywall__panel {
  position: relative; min-width: 0; min-height: 0; border-radius: 16px; background: var(--dmp-paywall-card);
  box-shadow: inset 0 0 0 1px var(--dmp-paywall-line), 0 18px 34px -30px color-mix(in oklch, var(--dmp-paywall-ink) 60%, transparent);
  animation: dmp-paywall-rise .7s var(--dmp-paywall-out) both; animation-delay: calc(var(--i, 0) * 80ms);
}
.dmp-paywall__ph {
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px 12px;
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--dmp-paywall-faint); }
}
.dmp-paywall__note { font-size: 11.5px; color: var(--dmp-paywall-faint); font-variant-numeric: tabular-nums; }

/* ---------- funnel */
.dmp-paywall__funnel { display: grid; grid-template-columns: minmax(0, 1fr) 286px; gap: 14px; }
.dmp-paywall__flow { display: flex; flex-direction: column; gap: 6px; padding: 14px 16px 12px; }
.dmp-paywall__sankey { position: relative; flex: 1; min-height: 0; }
.dmp-paywall__sankey svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.dmp-paywall__sankey .ribbons, .dmp-paywall__sankey .nodes { clip-path: inset(0 0 0 0); }
.dmp-paywall__sankey.enter :is(.ribbons, .nodes) { animation: dmp-paywall-wipe 1.3s var(--dmp-paywall-out) both; }
.dmp-paywall__sankey path {
  transition: d .85s var(--dmp-paywall-spring), opacity .35s, fill .35s;
  &.drop { fill: color-mix(in oklch, var(--dmp-paywall-accent) 10%, color-mix(in oklch, var(--dmp-paywall-ink) 6%, transparent)); }
  &.node { fill: var(--dmp-paywall-ink); }
  &.node.last { fill: var(--dmp-paywall-good); }
  &.sink { fill: color-mix(in oklch, var(--dmp-paywall-accent) 34%, color-mix(in oklch, var(--dmp-paywall-ink) 20%, transparent)); }
  &.off { opacity: 0; }
}
.dmp-paywall__sankey[data-sel] path { opacity: .62; }
.dmp-paywall__sankey.stepped path.main { filter: saturate(1.1); }
.dmp-paywall__sankey[data-sel] path.on { opacity: 1; }
.dmp-paywall__sankey[data-sel] path.drop.on { fill: color-mix(in oklch, var(--dmp-paywall-accent) 22%, transparent); }
.dmp-paywall__sankey path.hov { opacity: 1; filter: brightness(.94) saturate(1.2); }
.dmp-paywall__sankey path.drop.hov { fill: color-mix(in oklch, var(--dmp-paywall-accent) 22%, transparent); }
.dmp-paywall__stages { position: absolute; inset: 0; pointer-events: none; }
.dmp-paywall__stage {
  position: absolute; left: 0; top: 0; width: 132px; padding: 4px 6px 6px; overflow: hidden; border-radius: 9px; pointer-events: auto;
  transition: transform .85s var(--dmp-paywall-spring), opacity .35s, background-color .2s, box-shadow .2s;
  & small { display: block; font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dmp-paywall-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & b { display: block; font-size: clamp(16px, 1.8cqi, 20px); font-weight: 740; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.15; }
  & span { display: block; font: 600 10.5px var(--dmp-paywall-mono); color: var(--dmp-paywall-mute); font-variant-numeric: tabular-nums; }
  &:hover { background: var(--dmp-paywall-soft); }
  &[aria-checked="true"] { background: var(--dmp-paywall-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dmp-paywall-accent) 35%, transparent); & small { color: var(--dmp-paywall-accent); } }
  &.off { opacity: 0; pointer-events: none; visibility: hidden; }
}
.dmp-paywall__drops { position: absolute; inset: 0; pointer-events: none; }
.dmp-paywall__droplbl {
  position: absolute; left: 0; top: 0; width: 150px; padding-left: 8px; border-left: 2px solid color-mix(in oklch, var(--dmp-paywall-ink) 22%, transparent);
  font-size: 11.5px; line-height: 1.3; color: var(--dmp-paywall-mute);
  transition: transform .85s var(--dmp-paywall-spring), opacity .35s;
  & b { display: block; color: var(--dmp-paywall-accent); font-weight: 700; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & span { font: 600 10.5px var(--dmp-paywall-mono); color: var(--dmp-paywall-faint); }
  & em { display: block; font-style: normal; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &.off { opacity: 0; }
}
.dmp-paywall__sankey.compact {
  & .dmp-paywall__stage { padding: 3px 4px; & span { display: none; } & small { font-size: 9px; letter-spacing: .03em; } & b { font-size: 14px; } }
  & .dmp-paywall__droplbl em { display: none; }
  & .dmp-paywall__droplbl b { font-size: 11px; }
  & .dmp-paywall__droplbl span { display: block; }
}
.dmp-paywall__tip {
  position: absolute; left: 0; top: 0; z-index: 5; max-width: 240px; padding: 9px 11px; border-radius: 10px; pointer-events: none;
  background: var(--dmp-paywall-ink); color: var(--dmp-paywall-bg); font-size: 12px; line-height: 1.4;
  box-shadow: 0 16px 30px -14px color-mix(in oklch, var(--dmp-paywall-ink) 80%, transparent);
  opacity: 0; transition: opacity .15s;
  & b { font-variant-numeric: tabular-nums; }
  & small { display: block; color: color-mix(in oklch, var(--dmp-paywall-bg) 70%, var(--dmp-paywall-ink)); font-size: 11px; }
  &.on { opacity: 1; }
}

/* stage detail */
.dmp-paywall__detail {
  overflow: auto; padding: 16px; display: grid; align-content: start; gap: 14px;
  & h3 { font: 700 19px/1.15 var(--dmp-paywall-serif); letter-spacing: -.01em; text-wrap: balance; }
  & .big { font-size: 34px; font-weight: 760; letter-spacing: -.045em; line-height: 1; font-variant-numeric: tabular-nums; }
  & .rates { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  & .rates div { padding: 8px 10px; border-radius: 10px; background: var(--dmp-paywall-soft); }
  & .rates dt { font-size: 10.5px; color: var(--dmp-paywall-faint); }
  & .rates dd { font-size: 16px; font-weight: 720; font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & .lost { font-size: 12px; color: var(--dmp-paywall-mute); text-wrap: pretty; padding: 10px 12px; border-radius: 10px; border: 1px dashed var(--dmp-paywall-line); }
  & .lost b { color: var(--dmp-paywall-accent); font-variant-numeric: tabular-nums; }
  & h4 { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-paywall-faint); }
  & .mixrow { display: grid; grid-template-columns: 74px minmax(0, 1fr) 44px; align-items: center; gap: 8px; margin-top: 7px; font-size: 12px; }
  & .mixrow .bars { display: grid; gap: 2px; }
  & .mixrow .bars i { display: block; height: 7px; border-radius: 3px; width: calc(var(--v) * 1%); background: var(--c); transform-origin: left; animation: dmp-paywall-grow .7s var(--dmp-paywall-out) both; animation-delay: calc(var(--i, 0) * 50ms); }
  & .mixrow .bars i.base { height: 3px; background: color-mix(in oklch, var(--c) 35%, transparent); }
  & .mixrow b { text-align: right; font: 650 11px var(--dmp-paywall-mono); font-variant-numeric: tabular-nums; }
  & .mixrow b.hi { color: var(--dmp-paywall-good); }
  & .mixrow b.lo { color: var(--dmp-paywall-accent); }
  & .mixrow.dim { opacity: .45; }
  & .foot { font-size: 11px; color: var(--dmp-paywall-faint); text-wrap: pretty; }
}

/* ---------- experiment */
.dmp-paywall__test {
  display: grid; gap: 14px;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "vars vars" "cum forest";
}
.dmp-paywall__variants { grid-area: vars; display: grid; grid-template-columns: 1fr 1fr 1.15fr; gap: 0; padding: 0; overflow: hidden; }
.dmp-paywall__var {
  padding: 14px 16px; border-right: 1px solid var(--dmp-paywall-line);
  & h3 { margin-top: 3px; font: 700 15.5px/1.2 var(--dmp-paywall-serif); }
  & dl { display: grid; grid-template-columns: repeat(3, auto); justify-content: start; gap: 4px 18px; margin-top: 10px; }
  & dt { font-size: 10.5px; color: var(--dmp-paywall-faint); }
  & dd { font-size: 17px; font-weight: 720; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  &.b .dmp-paywall__cap { color: var(--dmp-paywall-accent); }
}
.dmp-paywall__verdict {
  padding: 14px 16px; display: grid; align-content: start; gap: 8px; background: var(--dmp-paywall-tint);
  & .v { display: flex; align-items: baseline; gap: 8px; }
  & .v b { font-size: 26px; font-weight: 760; letter-spacing: -.04em; color: var(--dmp-paywall-good); font-variant-numeric: tabular-nums; }
  & p { font-size: 12px; color: var(--dmp-paywall-mute); text-wrap: pretty; }
  & p b { color: var(--dmp-paywall-ink); font-variant-numeric: tabular-nums; }
  & .row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
}
.dmp-paywall__btn {
  display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px; border-radius: 9px; font-size: 12.5px; font-weight: 660;
  background: var(--dmp-paywall-ink); color: var(--dmp-paywall-bg); transition: background-color .2s, scale .2s var(--dmp-paywall-out), opacity .2s;
  &:hover { background: color-mix(in oklch, var(--dmp-paywall-ink) 86%, var(--dmp-paywall-accent)); }
  &:active { scale: .97; }
  &.ghost { background: none; color: var(--dmp-paywall-ink); box-shadow: inset 0 0 0 1px var(--dmp-paywall-line); &:hover { background: var(--dmp-paywall-soft); } }
  &.go { background: var(--dmp-paywall-good); }
  &:disabled { opacity: .45; cursor: not-allowed; }
}
.dmp-paywall__ship { position: relative; height: 6px; border-radius: 3px; background: var(--dmp-paywall-hair); overflow: hidden; & i { position: absolute; inset: 0; background: var(--dmp-paywall-good); transform-origin: left; transform: scaleX(var(--p, 0)); transition: transform .25s linear; } }
.dmp-paywall__cum { grid-area: cum; display: flex; flex-direction: column; gap: 8px; padding: 14px 16px 10px; }
.dmp-paywall__cumplot { position: relative; flex: 1; min-height: 0; cursor: crosshair; }
.dmp-paywall__cumplot svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.dmp-paywall__cumplot {
  & .grid line { stroke: var(--dmp-paywall-hair); }
  & .grid text, & .xl text { font: 10px var(--dmp-paywall-mono); fill: var(--dmp-paywall-faint); }
  & .a { --col: color-mix(in oklch, var(--dmp-paywall-ink) 55%, var(--dmp-paywall-bg)); }
  & .b { --col: var(--dmp-paywall-accent); }
  & .band { fill: var(--col); opacity: .13; }
  & .ln { fill: none; stroke: var(--col); stroke-width: 2.2; stroke-linejoin: round; stroke-linecap: round; }
  & circle, & .end text { fill: var(--col); }
  & .ln.draw { stroke-dasharray: 1; stroke-dashoffset: 1; animation: dmp-paywall-draw 1.2s var(--dmp-paywall-out) .15s forwards; }
  & .end text { font: 650 11px var(--dmp-paywall-sans); }
  & .cross { stroke: var(--dmp-paywall-faint); stroke-dasharray: 3 3; opacity: 0; }
  & .dot { opacity: 0; stroke: var(--dmp-paywall-card); stroke-width: 2; transition: opacity .15s; }
  &:hover .cross, &:hover .dot { opacity: 1; }
}
.dmp-paywall__forest { grid-area: forest; overflow: auto; padding: 14px 16px; display: flex; flex-direction: column; gap: 6px; }
.dmp-paywall__frows { display: grid; gap: 2px; }
.dmp-paywall__frow {
  display: grid; grid-template-columns: 84px minmax(0, 1fr) 58px; align-items: center; gap: 10px; padding: 5px 4px; border-radius: 8px; font-size: 12px;
  & .ax { position: relative; height: 22px; }
  & .ax::before { content: ""; position: absolute; top: 0; bottom: 0; left: var(--z); width: 1px; background: var(--dmp-paywall-line); }
  & .ci { position: absolute; top: 50%; height: 2px; margin-top: -1px; left: var(--l); width: var(--w); background: var(--col); border-radius: 1px; transform-origin: var(--z0) 50%; animation: dmp-paywall-grow .8s var(--dmp-paywall-out) both; animation-delay: calc(var(--i, 0) * 60ms + 200ms); }
  & .pt { position: absolute; top: 50%; left: var(--p); width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 50%; background: var(--col); box-shadow: 0 0 0 2px var(--dmp-paywall-card); animation: dmp-paywall-pop .5s var(--dmp-paywall-spring) both; animation-delay: calc(var(--i, 0) * 60ms + 420ms); }
  & b { text-align: right; font: 650 11.5px var(--dmp-paywall-mono); color: var(--col); font-variant-numeric: tabular-nums; }
  &.all { font-weight: 700; background: var(--dmp-paywall-soft); }
  &.sig { --col: var(--dmp-paywall-good); }
  &:not(.sig) { --col: var(--dmp-paywall-faint); }
  &.axis { padding-top: 0; & .ax { height: 14px; } & .ax span { position: absolute; top: 0; translate: -50% 0; font: 10px var(--dmp-paywall-mono); color: var(--dmp-paywall-faint); } }
}
.dmp-paywall__fnote { font-size: 11px; color: var(--dmp-paywall-faint); text-wrap: pretty; margin-top: auto; padding-top: 6px; }

/* ---------- plans */
.dmp-paywall__plans { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); gap: 14px; }
.dmp-paywall__mixp { padding: 14px 16px; overflow: auto; display: flex; flex-direction: column; gap: 10px; }
.dmp-paywall__mixrows { display: grid; gap: 12px; margin-top: 6px; }
.dmp-paywall__mixrow {
  display: grid; gap: 5px;
  & header { display: flex; justify-content: space-between; font-size: 12px; font-weight: 650; }
  & header span { font-weight: 500; color: var(--dmp-paywall-faint); font-variant-numeric: tabular-nums; }
  & .st { display: flex; height: 22px; border-radius: 6px; overflow: hidden; gap: 2px; }
  & .st i { flex: var(--v) 1 0; min-width: 0; background: var(--c); transition: flex-grow .7s var(--dmp-paywall-spring); display: grid; place-items: center; font: 650 10px var(--dmp-paywall-mono); font-style: normal; color: var(--dmp-paywall-card); overflow: hidden; white-space: nowrap; }
}
.dmp-paywall__legend { display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: auto; padding-top: 8px; font-size: 11.5px; color: var(--dmp-paywall-mute); & li { display: flex; align-items: center; gap: 6px; } & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); } }
.dmp-paywall__ptable {
  overflow: auto; padding: 8px 6px 6px;
  & table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
  & caption { text-align: left; padding: 6px 10px 10px; }
  & th { position: sticky; top: 0; background: var(--dmp-paywall-card); text-align: right; font-weight: 600; font-size: 11px; color: var(--dmp-paywall-faint); border-bottom: 1px solid var(--dmp-paywall-line); padding: 0; }
  & th:first-child, & td:first-child { text-align: left; }
  & th button { width: 100%; padding: 8px 8px; white-space: nowrap; text-align: inherit; display: inline-flex; gap: 4px; justify-content: flex-end; align-items: center; border-radius: 6px; }
  & th:first-child button { justify-content: flex-start; }
  & th button:hover { color: var(--dmp-paywall-ink); }
  & th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; opacity: 0; }
  & th[aria-sort="descending"] button { color: var(--dmp-paywall-ink); &::after { opacity: 1; border-top-color: currentColor; translate: 0 2px; } }
  & th[aria-sort="ascending"] button { color: var(--dmp-paywall-ink); &::after { opacity: 1; border-bottom-color: currentColor; translate: 0 -2px; } }
  & td { padding: 10px 8px; text-align: right; border-bottom: 1px solid var(--dmp-paywall-hair); font-size: 12.5px; white-space: nowrap; }
  & td:first-child { font-weight: 650; }
  & td:first-child i { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 8px; background: var(--c); }
  & td small { display: block; font-weight: 450; font-size: 11px; color: var(--dmp-paywall-faint); margin-left: 17px; }
  & tfoot td { font-weight: 720; border-bottom: 0; border-top: 1px solid var(--dmp-paywall-line); }
  & tbody tr { transition: background-color .2s; }
  & tbody tr:hover { background: var(--dmp-paywall-soft); }
  & .bar { display: inline-block; width: 34px; height: 6px; margin-right: 8px; border-radius: 3px; background: var(--dmp-paywall-hair); vertical-align: 1px; overflow: hidden; }
  & .bar::after { content: ""; display: block; height: 100%; width: calc(var(--v) * 1%); background: var(--c); }
}

.dmp-paywall__toast {
  position: absolute; right: 18px; bottom: 18px; z-index: 30; max-width: min(360px, calc(100% - 36px)); padding: 10px 14px; border-radius: 12px; pointer-events: none;
  background: var(--dmp-paywall-ink); color: var(--dmp-paywall-bg); font-weight: 600; font-size: 12.5px;
  box-shadow: 0 18px 36px -16px color-mix(in oklch, var(--dmp-paywall-ink) 80%, transparent);
  opacity: 0; translate: 0 10px; transition: opacity .25s, translate .5s var(--dmp-paywall-spring);
  &.on { opacity: 1; translate: 0 0; }
  &:empty { display: none; }
}

@keyframes dmp-paywall-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dmp-paywall-grow { from { transform: scaleX(0); } }
@keyframes dmp-paywall-pop { from { transform: scale(0); } }
@keyframes dmp-paywall-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dmp-paywall-draw { to { stroke-dashoffset: 0; } }

@container (width < 1000px) {
  .dmp-paywall__shell { grid-template-columns: 64px minmax(0, 1fr); }
  .dmp-paywall__side { align-items: center; padding: 18px 10px; }
  .dmp-paywall__lbl { display: none; }
  .dmp-paywall__brand { padding: 0 0 14px; }
  .dmp-paywall__nav button { padding: 10px; justify-content: center; }
  .dmp-paywall__funnel { grid-template-columns: minmax(0, 1fr) 250px; }
  .dmp-paywall__variants { grid-template-columns: 1fr 1fr; & .dmp-paywall__verdict { grid-column: 1 / -1; } }
}
@container (width < 760px) {
  .dmp-paywall__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dmp-paywall__side { flex-direction: row; align-items: center; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dmp-paywall-line); }
  .dmp-paywall__brand { padding: 0 8px 0 0; }
  .dmp-paywall__nav { display: flex; gap: 4px; }
  .dmp-paywall__main { display: flex; flex-direction: column; gap: 14px; overflow: auto; overscroll-behavior: contain; padding: 14px; & > * { flex: none; } }
  .dmp-paywall__funnel, .dmp-paywall__plans { grid-template-columns: minmax(0, 1fr); }
  .dmp-paywall__flow { height: 400px; }
  .dmp-paywall__test { grid-template-columns: minmax(0, 1fr); grid-template-rows: none; grid-template-areas: "vars" "cum" "forest"; }
  .dmp-paywall__cum { height: 300px; }
}
@container (width < 560px) {
  .dmp-paywall__variants { grid-template-columns: minmax(0, 1fr); & .dmp-paywall__var { border-right: 0; border-bottom: 1px solid var(--dmp-paywall-line); } }
  .dmp-paywall__seglbl { display: none; }
  .dmp-paywall__frow { grid-template-columns: 70px minmax(0, 1fr) 52px; }
}

@media (prefers-reduced-motion: reduce) {
  .dmp-paywall__panel, .dmp-paywall__prog i, .dmp-paywall__detail .mixrow .bars i, .dmp-paywall__frow .ci, .dmp-paywall__frow .pt { animation: none; }
  .dmp-paywall__sankey.enter :is(.ribbons, .nodes) { animation: none; }
  .dmp-paywall__sankey path, .dmp-paywall__stage, .dmp-paywall__droplbl, .dmp-paywall__mixrow .st i { transition: opacity .2s; }
