const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const nf = new Intl.NumberFormat('en-US');
const UID = 'dmp-paywall-' + Math.random().toString(36).slice(2, 8);
const NS = 'http://www.w3.org/2000/svg';

/* ------------------------------------------------------------ data
   Unique visitors per source and range, then a step rate per stage. Every stage count is
   rounded from the one before it, so drops are exact differences and All is the sum. */
const SRC = ['search', 'social', 'newsletter', 'direct'];
const SN = { all: 'All sources', search: 'Search', social: 'Social', newsletter: 'Newsletter', direct: 'Direct' };
const VIS = {
  7: { search: 118400, social: 61900, newsletter: 22300, direct: 37600 },
  28: { search: 402100, social: 197300, newsletter: 58900, direct: 111800 },
  90: { search: 1064000, social: 512600, newsletter: 121700, direct: 268300 }
};
const RATE = { search: [0.28, 0.035, 0.44, 0.62], social: [0.19, 0.022, 0.38, 0.55], newsletter: [0.57, 0.085, 0.52, 0.70], direct: [0.46, 0.061, 0.49, 0.67] };
const RF = { 7: [0.99, 1.05, 1.01, 1], 28: [1, 1, 1, 1], 90: [1.01, 0.94, 0.99, 1.01] };
const ST = [
  { name: 'Visitors', short: 'Visitors', drop: 'Stayed under the meter' },
  { name: 'Reached the wall', short: 'Hit the wall', drop: 'Left at the wall' },
  { name: 'Engaged the offer', short: 'Clicked offer', drop: 'Viewed plans, didn’t pick one' },
  { name: 'Started checkout', short: 'Checkout', drop: 'Abandoned payment' },
  { name: 'Subscribed', short: 'Subscribed' }
];
const counts = (r, s) => { const c = [VIS[r][s]]; for (let i = 0; i < 4; i++) c.push(Math.round(c[i] * RATE[s][i] * RF[r][i])); return c; };
const funnel = (r, s) => (s !== 'all' ? counts(r, s) : SRC.map((x) => counts(r, x)).reduce((a, c) => a.map((v, i) => v + c[i])));
function split(total, weights) {
  const sum = weights.reduce((a, b) => a + b, 0), raw = weights.map((w) => total * w / sum), out = raw.map(Math.floor);
  let left = total - out.reduce((a, b) => a + b, 0);
