  return out;
}
const pc = (a, b, d) => (b ? (a / b * 100).toFixed(d == null ? 1 : d) : '0') + '%';

/* ------------------------------------------------------------ state */
let view = 'funnel', range = 28, src = 'all', base = 0, scale = 'step', sel = 1, metric = 'conv', ship = 'idle', psort = { k: 'n', dir: -1 };

/* ------------------------------------------------------------ helpers */
const toastEl = $('[data-toast]');
let toastT = 0;
function toast(m) { toastEl.textContent = m; toastEl.classList.add('on'); clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) toastEl.classList.remove('on'); }, 2800); }
function radios(group, onPick) {
  const bs = $$('[role="radio"]', group);
  const pick = (b, quiet) => { bs.forEach((x) => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; }); if (!quiet) onPick(b); };
  group.addEventListener('click', (e) => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  group.addEventListener('keydown', (e) => {
    const i = bs.indexOf(document.activeElement); if (i < 0) return;
    const d = /Right|Down/.test(e.key) ? 1 : /Left|Up/.test(e.key) ? -1 : 0; if (!d) return;
    e.preventDefault(); const b = bs[(i + d + bs.length) % bs.length]; b.focus(); pick(b);
  });
  return pick;
}
function setD(p, d) { p.setAttribute('d', d); p.style.d = 'path("' + d + '")'; }
function tipAt(tip, host, x, y) {
  const r = host.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let l = x - r.left + 14; if (l + w > r.width - 4) l = x - r.left - w - 14;
  let t = y - r.top - h - 10; if (t < 0) t = y - r.top + 16;
  tip.style.transform = 'translate(' + Math.round(Math.max(0, l)) + 'px,' + Math.round(t) + 'px)';
}

/* ------------------------------------------------------------ sankey */
const sk = $('[data-sankey]'), svg = $('[data-svg]'), ribG = $('[data-ribbons]'), nodeG = $('[data-nodes]');
const stagesEl = $('[data-stages]'), dropsEl = $('[data-drops]'), tip = $('[data-tip]');
svg.querySelector('defs').innerHTML = '<linearGradient id="' + UID + '-g" gradientUnits="userSpaceOnUse" x1="0" x2="1000" y1="0" y2="0"><stop offset="0" class="s0"/><stop offset="1" class="s1"/></linearGradient>';
const grad = svg.querySelector('linearGradient');
grad.querySelector('.s0').setAttribute('stop-color', 'currentColor');
const P = { main: [], drop: [], node: [], sink: [] };
const mk = (cls, k) => { const p = document.createElementNS(NS, 'path'); p.setAttribute('class', cls); p.dataset.k = k; return p; };
for (let j = 0; j < 4; j++) { P.drop.push(ribG.appendChild(mk('drop', 'd' + j))); }
for (let j = 0; j < 4; j++) { const p = ribG.appendChild(mk('main', 'm' + j)); p.setAttribute('fill', 'url(#' + UID + '-g)'); P.main.push(p); }
for (let j = 0; j < 5; j++) P.node.push(nodeG.appendChild(mk('node' + (j === 4 ? ' last' : ''), 'n' + j)));
for (let j = 0; j < 4; j++) P.sink.push(nodeG.appendChild(mk('sink', 's' + j)));
ST.forEach((s, j) => {
  const b = document.createElement('button');
  b.type = 'button'; b.className = 'dmp-paywall__stage'; b.setAttribute('role', 'radio'); b.dataset.j = j;
  b.innerHTML = '<small>' + s.short + '</small><b></b><span></span>';
  stagesEl.appendChild(b);
});
for (let j = 0; j < 4; j++) { const d = document.createElement('div'); d.className = 'dmp-paywall__droplbl'; d.dataset.j = j; dropsEl.appendChild(d); }
const stageBtns = $$('.dmp-paywall__stage', stagesEl), dropLbls = $$('.dmp-paywall__droplbl', dropsEl);
/* resolve the gradient colours from the theme */
(function () {
  const pr = document.createElement('i'); pr.style.display = 'none'; root.appendChild(pr);
  const get = (v) => { pr.style.color = v; return getComputedStyle(pr).color; };
  grad.querySelector('.s0').setAttribute('stop-color', get('color-mix(in oklch, var(--dmp-paywall-ink) 30%, var(--dmp-paywall-card))'));
  grad.querySelector('.s1').setAttribute('stop-color', get('color-mix(in oklch, var(--dmp-paywall-accent) 90%, var(--dmp-paywall-card))'));
  pr.remove();
})();
let C = funnel(range, src);
const f2 = (v) => v.toFixed(1);
function layoutSankey() {
  const W = sk.clientWidth, H = sk.clientHeight; if (!W || !H) return;
