  const stepMode = scale === 'step', b0 = stepMode ? 0 : base;
  /* the last column keeps room for its label: solve the step so every label is step - 10 wide */
  const m = 5 - b0, lw = Math.max(64, Math.min(150, (W + 16) / m - 10)), padR = lw - nw - 6;
  const step = (W - padR - nw) / (m - 1), xs = [];
  for (let j = 0; j < 5; j++) xs[j] = j < b0 ? 0 : (j - b0) * step;
  sk.classList.toggle('compact', compact);
  sk.classList.toggle('stepped', stepMode);
  const avail = H - top - gap - foot;
  /* absolute: one scale for every column. each step: every column is 100% of the one
     before it, so each continuing ribbon becomes a lens that magnifies its slice */
  const Hn = avail * 0.64, Hs = avail - Hn, sc = avail / C[b0];
  const h = C.map((v, j) => (j < b0 ? 0 : stepMode ? Hn : Math.max(1.5, v * sc)));
  grad.setAttribute('x1', xs[b0]); grad.setAttribute('x2', xs[4] + nw);
  for (let j = 0; j < 5; j++) {
    const off = j < b0, x = off ? xs[b0] : xs[j], hh = off ? 0 : h[j];
    setD(P.node[j], 'M' + f2(x) + ' ' + top + 'L' + f2(x + nw) + ' ' + top + 'L' + f2(x + nw) + ' ' + f2(top + hh) + 'L' + f2(x) + ' ' + f2(top + hh) + 'Z');
    P.node[j].classList.toggle('off', off);
    const b = stageBtns[j];
    b.classList.toggle('off', off);
    b.style.width = lw + 'px';
    b.querySelector('b').textContent = nf.format(C[j]);
    b.querySelector('span').textContent = j === b0 ? 'start · 100%' : stepMode ? 'step ' + pc(C[j], C[j - 1]) : pc(C[j], C[b0], C[j] / C[b0] < 0.01 ? 2 : 1) + ' of start';
    const bx = x - 6;
    b.style.transform = 'translate(' + f2(bx) + 'px,' + (top - (compact ? 52 : 64)) + 'px)';
    b.setAttribute('aria-label', ST[j].name + ', ' + nf.format(C[j]));
  }
  for (let j = 0; j < 4; j++) {
    const off = j < b0, x0 = (off ? xs[b0] : xs[j]) + nw, x1 = off ? xs[b0] : xs[j + 1], xm = (x0 + x1) / 2;
    const p = C[j + 1] / C[j];
    const a = off ? 0 : stepMode ? Math.max(1, Hn * p) : h[j + 1], right = off ? 0 : stepMode ? Hn : h[j + 1];
    const bb = off ? 0 : Math.max(a + 0.5, h[j]);
    setD(P.main[j], 'M' + f2(x0) + ' ' + top + 'L' + f2(x1) + ' ' + top + 'L' + f2(x1) + ' ' + f2(top + right) + 'L' + f2(x0) + ' ' + f2(top + a) + 'Z');
    const y0a = top + a, y0b = top + bb;
    const y1a = off ? top : stepMode ? top + Hn + gap : top + a + gap;
    const y1b = off ? top : stepMode ? y1a + Math.max(1, Hs * (1 - p)) : top + bb + gap;
    const c1 = y0a + (right - a) / 2;
    setD(P.drop[j], 'M' + f2(x0) + ' ' + f2(y0a) + 'C' + f2(xm) + ' ' + f2(c1) + ' ' + f2(xm) + ' ' + f2(y1a) + ' ' + f2(x1) + ' ' + f2(y1a) +
      'L' + f2(x1) + ' ' + f2(y1b) + 'C' + f2(xm) + ' ' + f2(y1b) + ' ' + f2(xm) + ' ' + f2(y0b) + ' ' + f2(x0) + ' ' + f2(y0b) + 'Z');
    setD(P.sink[j], 'M' + f2(x1) + ' ' + f2(y1a) + 'L' + f2(x1 + nw) + ' ' + f2(y1a) + 'L' + f2(x1 + nw) + ' ' + f2(y1b) + 'L' + f2(x1) + ' ' + f2(y1b) + 'Z');
    [P.main[j], P.drop[j], P.sink[j]].forEach((q) => q.classList.toggle('off', off));
    /* drop labels sit in a footer row under the column their sink belongs to */
    const lb = dropLbls[j], lost = C[j] - C[j + 1];
    lb.classList.toggle('off', off);
    lb.style.width = lw + 'px';
    lb.innerHTML = '<b>−' + nf.format(lost) + ' <span>' + pc(lost, C[j]) + '</span></b><em>' + ST[j].drop + '</em>';
    lb.style.transform = 'translate(' + f2(x1) + 'px,' + f2(H - foot + 6) + 'px)';
  }
