}
function highlight() {
  sk.dataset.sel = sel;
  const on = new Set(['n' + sel, 'm' + sel, 'd' + sel, 's' + sel, 'm' + (sel - 1)]);
  $$('path', svg).forEach((p) => p.classList.toggle('on', on.has(p.dataset.k)));
  stageBtns.forEach((b, j) => { const isOn = j === sel; b.setAttribute('aria-checked', String(isOn)); b.tabIndex = isOn ? 0 : -1; });
}
const pickStage = (j, focus) => { sel = j; highlight(); renderDetail(); if (focus) stageBtns[j].focus(); };
stagesEl.addEventListener('click', (e) => { const b = e.target.closest('.dmp-paywall__stage'); if (b && +b.dataset.j !== sel) pickStage(+b.dataset.j); });
stagesEl.addEventListener('keydown', (e) => {
  const d = /Right|Down/.test(e.key) ? 1 : /Left|Up/.test(e.key) ? -1 : 0; if (!d) return;
  e.preventDefault(); const j = Math.min(4, Math.max(scale === 'step' ? 0 : base, sel + d)); if (j !== sel) pickStage(j, true);
});
svg.addEventListener('pointermove', (e) => {
  const p = e.target.closest && e.target.closest('path');
  $$('path.hov', svg).forEach((x) => { if (x !== p) x.classList.remove('hov'); });
  if (!p || p.classList.contains('off')) { tip.classList.remove('on'); return; }
  p.classList.add('hov');
  const t = p.dataset.k[0], j = +p.dataset.k.slice(1);
  let html = '';
  if (t === 'n') html = '<b>' + ST[j].name + '</b><br>' + nf.format(C[j]) + ' readers<small>' + pc(C[j], C[0], 2) + ' of all visitors</small>';
  if (t === 'm') html = '<b>' + ST[j].name + ' → ' + ST[j + 1].name + '</b><br>' + nf.format(C[j + 1]) + ' continue<small>' + pc(C[j + 1], C[j]) + ' step conversion</small>';
  if (t === 'd' || t === 's') html = '<b>' + ST[j].drop + '</b><br>' + nf.format(C[j] - C[j + 1]) + ' readers lost<small>' + pc(C[j] - C[j + 1], C[j]) + ' of “' + ST[j].name + '”</small>';
  tip.innerHTML = html; tip.classList.add('on'); tipAt(tip, sk, e.clientX, e.clientY);
});
svg.addEventListener('pointerleave', () => { tip.classList.remove('on'); $$('path.hov', svg).forEach((x) => x.classList.remove('hov')); });

/* ------------------------------------------------------------ stage detail */
const detail = $('[data-detail]');
function renderDetail() {
  const j = sel, all = SRC.map((s) => counts(range, s));
  const tot0 = all.reduce((a, c) => a + c[0], 0), totj = all.reduce((a, c) => a + c[j], 0);
  let h = '<p class="dmp-paywall__cap">Stage ' + (j + 1) + ' of 5 · ' + SN[src] + '</p><h3>' + ST[j].name + '</h3><div class="big">' + nf.format(C[j]) + '</div>' +
    '<dl class="rates"><div><dt>Step conversion</dt><dd>' + (j ? pc(C[j], C[j - 1], 1) : '—') + '</dd></div><div><dt>Of all visitors</dt><dd>' + pc(C[j], C[0], j > 1 ? 2 : 1) + '</dd></div></dl>';
  if (j < 4) h += '<p class="lost"><b>−' + nf.format(C[j] - C[j + 1]) + '</b> ' + ST[j].drop.toLowerCase() + ' (' + pc(C[j] - C[j + 1], C[j]) + '). ' + nf.format(C[j + 1]) + ' go on to “' + ST[j + 1].name.toLowerCase() + '”.</p>';
  else h += '<p class="lost">Every subscriber here paid. <button type="button" class="dmp-paywall__btn ghost" data-goplans>See the plans they chose</button></p>';
  h += '<div><h4>Source mix here vs at the door</h4>';
  SRC.forEach((s, i) => {
    const sh = all[i][j] / totj * 100, sv = all[i][0] / tot0 * 100, idx = Math.round(sh / sv * 100);
    h += '<div class="mixrow' + (src !== 'all' && src !== s ? ' dim' : '') + '" data-k="' + s + '" style="--i:' + i + '"><span>' + SN[s] + '</span><span class="bars"><i style="--v:' + sh.toFixed(1) + '"></i><i class="base" style="--v:' + sv.toFixed(1) + '"></i></span>' +
      '<b class="' + (idx >= 115 ? 'hi' : idx <= 85 ? 'lo' : '') + '" title="Share here ' + sh.toFixed(1) + '% vs ' + sv.toFixed(1) + '% of visitors">' + idx + '</b></div>';
  });
  h += '</div><p class="foot">Thick bar: share of this stage. Thin bar: share of visitors. Index 100 means a source keeps its share; newsletter readers over-index all the way down.</p>';
  detail.innerHTML = h;
  if (!RM) detail.animate([{ opacity: 0.3 }, { opacity: 1 }], { duration: 260, easing: 'ease-out' });
}
detail.addEventListener('click', (e) => { if (e.target.closest('[data-goplans]')) setView('plans'); });

/* ------------------------------------------------------------ experiment */
const T = {
  a: { name: 'A', rev: 20.44, seg: { search: [131200, 349], social: [64300, 57], newsletter: [19800, 341], direct: [36900, 335], mobile: [171500, 612], desktop: [80700, 470] } },
  b: { name: 'B', rev: 21.59, seg: { search: [130700, 401], social: [64900, 61], newsletter: [19600, 397], direct: [37200, 378], mobile: [171900, 701], desktop: [80500, 536] } }
};
['a', 'b'].forEach((v) => { const s = T[v].seg; s.all = SRC.reduce((acc, k) => [acc[0] + s[k][0], acc[1] + s[k][1]], [0, 0]); });
const DAYS = 18, DOW = [1.05, 1.08, 1.06, 1.04, 0.98, 0.86, 0.93];
let sd2 = 1409;
const rnd = () => (sd2 = (sd2 * 1664525 + 1013904223) >>> 0) / 4294967296;
const wN = Array.from({ length: DAYS }, (_, d) => DOW[d % 7] * (0.94 + rnd() * 0.12));
['a', 'b'].forEach((v) => {
  const [n, x] = T[v].seg.all;
  T[v].dn = split(n, wN.map((w) => w * 1000));
  T[v].dx = split(x, wN.map((w) => w * 1000 * (0.75 + rnd() * 0.5)));
});
const dayLabel = (d) => { const dt = 14 + d; return dt <= 30 ? dt + ' Sep' : (dt - 30) + ' Oct'; };
function erf(x) { const t = 1 / (1 + 0.3275911 * Math.abs(x)), y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x); return x >= 0 ? y : -y; }
function stats(seg) {
  const [nA, xA] = T.a.seg[seg], [nB, xB] = T.b.seg[seg], pA = xA / nA, pB = xB / nB;
  const adj = metric === 'rpm' ? Math.log(T.b.rev / T.a.rev) : 0;
  const lr = Math.log(pB / pA) + adj, se = Math.sqrt((1 - pA) / xA + (1 - pB) / xB);
  const pp = (xA + xB) / (nA + nB), z = (pB - pA) / Math.sqrt(pp * (1 - pp) * (1 / nA + 1 / nB));
