}
const sgn = (v, d) => (v >= 0 ? '+' : '−') + Math.abs(v * 100).toFixed(d == null ? 1 : d) + '%';
function renderVariants() {
  ['a', 'b'].forEach((v) => {
    const [n, x] = T[v].seg.all, p = x / n;
    $('[data-var="' + v + '"] [data-vstats]').innerHTML = '<div><dt>Visitors</dt><dd>' + nf.format(n) + '</dd></div><div><dt>Subscribers</dt><dd>' + nf.format(x) + '</dd></div>' +
      '<div><dt>' + (metric === 'conv' ? 'Conversion' : 'Revenue / 1k') + '</dt><dd>' + (metric === 'conv' ? (p * 100).toFixed(2) + '%' : '$' + (p * T[v].rev * 1000).toFixed(2)) + '</dd></div>';
  });
