  if (ship === 'confirm') act = '<p>End PW-14 and give every reader <b>Meter 3 · 30% off</b>?</p><div class="row"><button type="button" class="dmp-paywall__btn go" data-confirm>Confirm rollout</button><button type="button" class="dmp-paywall__btn ghost" data-cancel>Cancel</button></div>';
