  c.querySelector('i').style.setProperty('--p', done ? 100 : 64.3);
}

const cumHost = $('[data-cumplot]'), cumSvg = $('[data-cumsvg]'), tip2 = $('[data-tip2]');
let cumGeo = null, cumDrawn = false;
function cumSeries(v) {
  let n = 0, x = 0;
  return T[v].dn.map((dn, d) => { n += dn; x += T[v].dx[d]; const p = x / n; return { n, x, v: metric === 'conv' ? p * 100 : p * T[v].rev * 1000, p }; });
}
function renderCum() {
  const W = cumHost.clientWidth, H = cumHost.clientHeight; if (!W || !H) return;
  const L = 44, R = 64, Tp = 8, B = 22, pw = W - L - R, ph = H - Tp - B;
  const A = cumSeries('a'), Bs = cumSeries('b');
  const vals = A.concat(Bs).map((o) => o.v), lo = Math.min(...vals), hi = Math.max(...vals);
  const pad = (hi - lo) * 0.15, y0 = Math.max(0, lo - pad), y1 = hi + pad;
  const X = (d) => L + d / (DAYS - 1) * pw, Y = (v) => Tp + ph - (v - y0) / (y1 - y0) * ph;
  const fmt = (v) => (metric === 'conv' ? v.toFixed(2) + '%' : '$' + v.toFixed(0));
  let g = '<g class="grid">';
  for (let i = 0; i <= 4; i++) { const v = y0 + (y1 - y0) * i / 4, y = Y(v).toFixed(1); g += '<line x1="' + L + '" x2="' + (L + pw) + '" y1="' + y + '" y2="' + y + '"/><text x="' + (L - 8) + '" y="' + y + '" text-anchor="end" dominant-baseline="middle">' + fmt(v) + '</text>'; }
  g += '</g><g class="xl">';
  [0, 6, 12, 17].forEach((d) => { g += '<text x="' + X(d).toFixed(1) + '" y="' + (H - 4) + '" text-anchor="middle">' + dayLabel(d) + '</text>'; });
  g += '</g>';
  const band = (S, v) => {
    /* 95% band for the cumulative rate, from its running sample size */
    const up = S.map((o, d) => { const se = Math.sqrt(o.p * (1 - o.p) / o.n), k = metric === 'conv' ? 100 : T[v].rev * 1000; return X(d).toFixed(1) + ' ' + Y(Math.min(y1, o.v + 1.96 * se * k)).toFixed(1); });
    const dn = S.map((o, d) => { const se = Math.sqrt(o.p * (1 - o.p) / o.n), k = metric === 'conv' ? 100 : T[v].rev * 1000; return X(d).toFixed(1) + ' ' + Y(Math.max(y0, o.v - 1.96 * se * k)).toFixed(1); }).reverse();
    return '<path class="band ' + v + '" d="M' + up.join('L') + 'L' + dn.join('L') + 'Z"/>';
  };
  const line = (S, v) => '<path class="ln ' + v + (cumDrawn || RM ? '' : ' draw') + '" pathLength="1" d="M' + S.map((o, d) => X(d).toFixed(1) + ' ' + Y(o.v).toFixed(1)).join('L') + '"/>';
  const end = (S, v, nm) => '<g class="end ' + v + '"><circle class="' + v + '" cx="' + X(DAYS - 1).toFixed(1) + '" cy="' + Y(S[DAYS - 1].v).toFixed(1) + '" r="3.5"/><text class="' + v + '" x="' + (X(DAYS - 1) + 8).toFixed(1) + '" y="' + Y(S[DAYS - 1].v).toFixed(1) + '" dominant-baseline="middle" style="stroke:none">' + nm + ' ' + fmt(S[DAYS - 1].v) + '</text></g>';
  cumSvg.innerHTML = g + band(A, 'a') + band(Bs, 'b') + line(A, 'a') + line(Bs, 'b') + end(A, 'a', 'A') + end(Bs, 'b', 'B') +
    '<line class="cross" y1="' + Tp + '" y2="' + (Tp + ph) + '"/><circle class="dot a" r="4"/><circle class="dot b" r="4"/>';
  cumDrawn = true;
  cumGeo = { X, Y, L, pw, A, B: Bs, fmt };
}
cumHost.addEventListener('pointermove', (e) => {
  if (!cumGeo) return;
  const r = cumHost.getBoundingClientRect(), d = Math.max(0, Math.min(DAYS - 1, Math.round((e.clientX - r.left - cumGeo.L) / cumGeo.pw * (DAYS - 1))));
  const x = cumGeo.X(d).toFixed(1), a = cumGeo.A[d], b = cumGeo.B[d];
  const cr = cumSvg.querySelector('.cross'); cr.setAttribute('x1', x); cr.setAttribute('x2', x);
  const da = cumSvg.querySelector('.dot.a'), db = cumSvg.querySelector('.dot.b');
  da.setAttribute('cx', x); da.setAttribute('cy', cumGeo.Y(a.v)); db.setAttribute('cx', x); db.setAttribute('cy', cumGeo.Y(b.v));
  tip2.innerHTML = '<b>Day ' + (d + 1) + ' · ' + dayLabel(d) + '</b><br>A ' + cumGeo.fmt(a.v) + ' · ' + nf.format(a.x) + ' of ' + nf.format(a.n) + '<br>B ' + cumGeo.fmt(b.v) + ' · ' + nf.format(b.x) + ' of ' + nf.format(b.n) +
    '<small>Running totals since 14 Sep</small>';
  tip2.classList.add('on'); tipAt(tip2, cumHost, e.clientX, e.clientY);
});
cumHost.addEventListener('pointerleave', () => tip2.classList.remove('on'));

const forestEl = $('[data-forest]');
function renderForest() {
  const D0 = -0.3, D1 = 0.7, pos = (v) => ((Math.max(D0, Math.min(D1, v)) - D0) / (D1 - D0) * 100).toFixed(2) + '%';
  const SEGS = [['all', 'All readers'], ['search', 'Search'], ['social', 'Social'], ['newsletter', 'Newsletter'], ['direct', 'Direct'], ['mobile', 'Mobile'], ['desktop', 'Desktop']];
  let h = '<div class="dmp-paywall__frow axis" aria-hidden="true"><span></span><span class="ax" style="--z:' + pos(0) + '">' + [-0.2, 0, 0.2, 0.4, 0.6].map((v) => '<span style="left:' + pos(v) + '">' + (v > 0 ? '+' : '') + Math.round(v * 100) + '%</span>').join('') + '</span><span></span></div>';
  SEGS.forEach(([k, nm], i) => {
    const s = stats(k);
    h += '<div class="dmp-paywall__frow' + (k === 'all' ? ' all' : '') + (s.sig ? ' sig' : '') + '" style="--i:' + i + '" title="' + nm + ': ' + sgn(s.lift) + ' (95% interval ' + sgn(s.lo) + ' to ' + sgn(s.hi) + ')">' +
      '<span>' + nm + '</span><span class="ax" style="--z:' + pos(0) + '"><i class="ci" style="--l:' + pos(s.lo) + ';--w:calc(' + pos(s.hi) + ' - ' + pos(s.lo) + ');--z0:' + ((0 - Math.max(D0, s.lo)) / (Math.min(D1, s.hi) - Math.max(D0, s.lo)) * 100).toFixed(1) + '%"></i><i class="pt" style="--p:' + pos(s.lift) + '"></i></span><b>' + sgn(s.lift, 0) + '</b></div>';
  });
  const weak = SEGS.filter(([k]) => !stats(k).sig).map(([, nm]) => nm);
  h += '<p class="dmp-paywall__fnote">Green rows exclude zero. ' + (weak.length ? weak.join(', ').replace(/, ([^,]*)$/, ' and $1') + (weak.length > 1 ? ' still overlap' : ' still overlaps') + ' zero and need more readers.' : 'Every segment clears zero.') + '</p>';
  forestEl.innerHTML = h;
}
radios($('[data-metric]'), (b) => {
  metric = b.dataset.v;
  $('[data-cumtitle]').textContent = metric === 'conv' ? 'Cumulative conversion, by test day' : 'Cumulative revenue per 1k visitors, by test day';
  renderVariants(); renderCum(); renderForest();
});

/* ------------------------------------------------------------ plans */
const PLANS = [
  { k: 'monthly', name: 'Monthly', price: '$12 a month', val: 144 },
  { k: 'annual', name: 'Annual', price: '$96 a year', val: 96 },
  { k: 'student', name: 'Student', price: '$4 a month', val: 48 },
  { k: 'gift', name: 'Gift', price: '$90 a year', val: 90 }
];
const MIX = { search: [58, 27, 9, 6], social: [66, 14, 16, 4], newsletter: [41, 46, 3, 10], direct: [49, 38, 4, 9] };
function planData() {
  const per = {}; SRC.forEach((s) => { per[s] = split(counts(range, s)[4], MIX[s]); });
  const use = src === 'all' ? SRC : [src];
  const rows = PLANS.map((p, i) => { const n = use.reduce((a, s) => a + per[s][i], 0); return Object.assign({}, p, { n, rev: n * p.val }); });
  const tot = rows.reduce((a, r) => a + r.n, 0);
  rows.forEach((r) => { r.share = tot ? r.n / tot : 0; });
  return { per, rows, tot };
}
function renderPlans() {
  const { per, rows, tot } = planData();
  $('[data-mixrows]').innerHTML = SRC.map((s) => {
    const n = per[s].reduce((a, b) => a + b, 0);
    return '<div class="dmp-paywall__mixrow" style="' + (src !== 'all' && src !== s ? 'opacity:.4' : '') + '"><header>' + SN[s] + '<span>' + nf.format(n) + ' subscribers</span></header><div class="st">' +
      per[s].map((c, i) => '<i data-k="' + PLANS[i].k + '" style="--v:' + c + '" title="' + PLANS[i].name + ': ' + nf.format(c) + '">' + (n && c / n > 0.12 ? Math.round(c / n * 100) + '%' : '') + '</i>').join('') + '</div></div>';
  }).join('');
  $('[data-mixnote]').textContent = SN[src] + ' · ' + range + ' days';
  $('[data-plegend]').innerHTML = PLANS.map((p) => '<li data-k="' + p.k + '"><i></i>' + p.name + '</li>').join('');
  const sorted = rows.slice().sort((a, b) => (psort.k === 'name' ? a.name.localeCompare(b.name) : a[psort.k] - b[psort.k]) * psort.dir);
  const mx = Math.max(...rows.map((r) => r.share), 0.0001);
  $('[data-pbody]').innerHTML = sorted.map((r) => '<tr data-k="' + r.k + '"><td><i></i>' + r.name + '<small>' + r.price + '</small></td><td>' + nf.format(r.n) + '</td><td><span class="bar" style="--v:' + (r.share / mx * 100).toFixed(1) + '"></span>' + (r.share * 100).toFixed(1) + '%</td><td>$' + r.val + '</td><td>$' + nf.format(r.rev) + '</td></tr>').join('');
  $('[data-pfoot]').innerHTML = '<tr><td>Total</td><td>' + nf.format(tot) + '</td><td>100%</td><td>$' + (tot ? (rows.reduce((a, r) => a + r.rev, 0) / tot).toFixed(2) : '0') + '</td><td>$' + nf.format(rows.reduce((a, r) => a + r.rev, 0)) + '</td></tr>';
  $('[data-pcap]').textContent = 'New subscriptions by plan · ' + SN[src] + ' · ' + range + ' days · matches the funnel’s ' + nf.format(C[4]) + ' subscribers';
  $$('th[aria-sort]', root).forEach((th) => { const k = th.querySelector('button').dataset.sort; th.setAttribute('aria-sort', k === psort.k ? (psort.dir > 0 ? 'ascending' : 'descending') : 'none'); });
}
$('.dmp-paywall__ptable thead').addEventListener('click', (e) => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  psort = { k, dir: psort.k === k ? -psort.dir : (k === 'name' ? 1 : -1) };
  const rowsBefore = new Map($$('[data-pbody] tr').map((tr) => [tr.dataset.k, tr.getBoundingClientRect().top]));
  renderPlans();
  if (!RM) $$('[data-pbody] tr').forEach((tr) => { const f = rowsBefore.get(tr.dataset.k); if (f == null) return; const dy = f - tr.getBoundingClientRect().top; if (dy) tr.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 480, easing: 'cubic-bezier(.22,1,.36,1)' }); });
});

/* ------------------------------------------------------------ chrome: views, filters */
const KICK = { funnel: 'Paywall funnel', test: 'Offer test PW-14 · 14 Sep – 1 Oct 2026', plans: 'New subscriptions' };
const H2 = { funnel: 'From first visit to paid subscriber', test: 'Does a tighter meter with a softer price win?', plans: 'What new subscribers chose' };
function setHead() {
  $('[data-kicker]').textContent = view === 'test' ? KICK.test : KICK[view] + ' · last ' + range + ' days · ' + SN[src];
  $('[data-h2]').textContent = H2[view];
  $('[data-ctrls]').hidden = view === 'test';
}
const navBtns = $$('[data-nav] button');
function setView(v) {
  view = v;
  navBtns.forEach((b) => { const on = b.dataset.view === v; if (on) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); b.tabIndex = on ? 0 : -1; });
  $$('.dmp-paywall__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  setHead();
  if (v === 'funnel') { layoutSankey(); renderDetail(); }
  if (v === 'test') { renderVariants(); renderCum(); renderForest(); }
  if (v === 'plans') renderPlans();
}
$('[data-nav]').addEventListener('click', (e) => { const b = e.target.closest('button[data-view]'); if (b && b.dataset.view !== view) setView(b.dataset.view); });
$('[data-nav]').addEventListener('keydown', (e) => {
  const i = navBtns.indexOf(document.activeElement); if (i < 0) return;
  const d = /Down|Right/.test(e.key) ? 1 : /Up|Left/.test(e.key) ? -1 : 0; if (!d) return;
  e.preventDefault(); const b = navBtns[(i + d + navBtns.length) % navBtns.length]; b.focus(); setView(b.dataset.view);
});
function refresh() {
  C = funnel(range, src); setHead();
  if (view === 'funnel') { layoutSankey(); renderDetail(); }
  if (view === 'plans') renderPlans();
}
radios($('[data-range]'), (b) => { range = +b.dataset.v; refresh(); });
radios($('[data-src]'), (b) => { src = b.dataset.v; refresh(); });
radios($('[data-base]'), (b) => {
  if (b.dataset.v === 'step') { scale = 'step'; base = 0; } else { scale = 'abs'; base = +b.dataset.v; }
  if (sel < base) sel = base; layoutSankey(); renderDetail();
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (view === 'funnel') layoutSankey();
  if (view === 'test') renderCum();
});
ro.observe(sk); ro.observe(cumHost);

/* ------------------------------------------------------------ mount */
if (!RM) { sk.classList.add('enter'); setTimeout(() => sk.classList.remove('enter'), 1500); }
setHead();
layoutSankey();
renderDetail();

css:
.dmp-churn {
  /* re-theme with these four */
  --dmp-churn-bg: oklch(0.205 0.024 196);
  --dmp-churn-ink: oklch(0.955 0.012 150);
  --dmp-churn-hi: oklch(0.88 0.17 124);
  --dmp-churn-loss: oklch(0.73 0.15 36);

  --dmp-churn-old: color-mix(in oklch, var(--dmp-churn-bg) 30%, oklch(0.6 0.085 205));
  --dmp-churn-panel: color-mix(in oklch, var(--dmp-churn-bg) 93%, var(--dmp-churn-ink));
  --dmp-churn-raise: color-mix(in oklch, var(--dmp-churn-bg) 87%, var(--dmp-churn-ink));
  --dmp-churn-line: color-mix(in oklch, var(--dmp-churn-ink) 12%, transparent);
  --dmp-churn-hair: color-mix(in oklch, var(--dmp-churn-ink) 6%, transparent);
  --dmp-churn-mute: color-mix(in oklch, var(--dmp-churn-ink) 66%, var(--dmp-churn-bg));
  --dmp-churn-faint: color-mix(in oklch, var(--dmp-churn-ink) 44%, var(--dmp-churn-bg));
  --dmp-churn-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dmp-churn-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dmp-churn-out: cubic-bezier(.16, 1, .3, 1);
  --dmp-churn-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);

  width: 100%;
  height: var(--dmp-churn-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background:
    radial-gradient(90% 70% at 100% 0%, color-mix(in oklch, var(--dmp-churn-hi) 6%, transparent), transparent 62%),
    var(--dmp-churn-bg);
  color: var(--dmp-churn-ink);
  font: 13px/1.45 var(--dmp-churn-sans);
  accent-color: var(--dmp-churn-hi);
  color-scheme: dark;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dmp-churn-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, h4, p, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dmp-churn-hi); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}

.dmp-churn__shell {
  height: 100%; display: grid; gap: 12px; padding: 14px 18px 18px;
  grid-template: "head" auto "kpis" auto "body" minmax(0, 1fr) / minmax(0, 1fr);
}

/* ---------- head */
.dmp-churn__head { grid-area: head; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 20px; }
.dmp-churn__brand {
  display: flex; align-items: center; gap: 10px;
  & svg { width: 34px; height: 34px; padding: 6px; border-radius: 10px; flex: none; background: var(--dmp-churn-hi); fill: none; stroke: var(--dmp-churn-bg); stroke-width: 2.2; stroke-linecap: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dmp-churn-mute); }
}
.dmp-churn__tabs {
  display: flex; gap: 2px;
  & button { position: relative; padding: 8px 11px; border-radius: 9px; font-weight: 640; color: var(--dmp-churn-mute); transition: color .2s, background-color .2s; }
  & button::after { content: ""; position: absolute; inset: auto 11px 2px; height: 2px; border-radius: 2px; background: var(--dmp-churn-hi); scale: 0 1; transition: scale .45s var(--dmp-churn-out); }
  & button:hover { color: var(--dmp-churn-ink); background: var(--dmp-churn-hair); }
  & button[aria-selected="true"] { color: var(--dmp-churn-ink); &::after { scale: 1 1; } }
}
.dmp-churn__filters { margin-left: auto; display: flex; flex-wrap: wrap; gap: 8px; }
.dmp-churn__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dmp-churn-hair); box-shadow: inset 0 0 0 1px var(--dmp-churn-line);
  & button { padding: 5px 10px; border-radius: 7px; font-size: 12px; font-weight: 620; white-space: nowrap; color: var(--dmp-churn-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dmp-churn-ink); }
  & button[aria-checked="true"] { background: var(--dmp-churn-ink); color: var(--dmp-churn-bg); }
  & button[aria-disabled="true"] { opacity: .38; cursor: not-allowed; text-decoration: line-through; text-decoration-thickness: 1px; }
}

/* ---------- kpis */
.dmp-churn__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; margin: 0; }
.dmp-churn__kpi {
  padding: 10px 14px 11px; border-radius: 13px; background: var(--dmp-churn-panel); box-shadow: inset 0 0 0 1px var(--dmp-churn-line);
  animation: dmp-churn-rise .6s var(--dmp-churn-out) both; animation-delay: calc(var(--i, 0) * 55ms);
  & dt { font-size: 11px; color: var(--dmp-churn-faint); letter-spacing: .01em; }
  & dd { display: flex; align-items: baseline; flex-wrap: wrap; gap: 2px 8px; margin-top: 2px; }
  & b { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 760; letter-spacing: -.035em; font-variant-numeric: tabular-nums; line-height: 1.1; }
  & small { font-size: 11px; color: var(--dmp-churn-mute); font-variant-numeric: tabular-nums; }
  &.bad b { color: var(--dmp-churn-loss); }
}

/* ---------- body */
.dmp-churn__body { grid-area: body; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 292px; gap: 12px; }
.dmp-churn__main, .dmp-churn__side {
  position: relative; min-width: 0; min-height: 0; border-radius: 15px; background: var(--dmp-churn-panel); box-shadow: inset 0 0 0 1px var(--dmp-churn-line);
  animation: dmp-churn-rise .7s var(--dmp-churn-out) both; animation-delay: calc(var(--i, 0) * 80ms + 140ms);
}
.dmp-churn__main { display: flex; flex-direction: column; }
.dmp-churn__view { display: flex; flex-direction: column; flex: 1; min-height: 0; padding: 12px 14px 10px; }
.dmp-churn__ph {
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 6px 12px; margin-bottom: 6px;
  & h3 { font-size: 10.5px; font-weight: 720; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-churn-mute); text-wrap: balance; }
}
.dmp-churn__key {
  display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--dmp-churn-faint);
  & i { display: block; width: 26px; height: 8px; border-radius: 2px; }
  & .ramp { background: linear-gradient(90deg, var(--dmp-churn-old), var(--dmp-churn-hi)); }
  & .cf { width: 18px; height: 0; border-top: 2px dashed var(--dmp-churn-hi); margin-left: 8px; }
}

/* ---------- layer cake */
.dmp-churn__chart { position: relative; flex: 1; min-height: 220px; border-radius: 8px; cursor: crosshair; touch-action: pan-y; }
.dmp-churn__chart svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.dmp-churn__grid {
  & line { stroke: var(--dmp-churn-hair); }
  & line.zero { stroke: var(--dmp-churn-line); }
  & text { fill: var(--dmp-churn-faint); font: 500 10.5px var(--dmp-churn-mono); font-variant-numeric: tabular-nums; }
}
.dmp-churn__xaxis text {
  fill: var(--dmp-churn-faint); font: 500 10.5px var(--dmp-churn-mono); text-anchor: middle;
  transition: opacity .3s, transform .8s var(--dmp-churn-spring);
  &.yr { fill: var(--dmp-churn-mute); font-weight: 700; }
}
.dmp-churn__bands {
  animation: dmp-churn-wipe 1.5s var(--dmp-churn-out) .25s both;
  & path {
    fill: color-mix(in oklch, var(--dmp-churn-hi) calc(var(--t, 0) * 100%), var(--dmp-churn-old));
    stroke: var(--dmp-churn-bg); stroke-width: .75; stroke-linejoin: round;
    transition: d .85s var(--dmp-churn-spring), opacity .3s, fill .3s, filter .2s;
  }
  & path.legacy { fill: color-mix(in oklch, var(--dmp-churn-ink) 16%, var(--dmp-churn-bg)); }
  & path.hov { filter: brightness(1.18); }
}
