  if (!SV) return;
  const d = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
  if (e.key === 'Home') { e.preventDefault(); readAt(0); return; }
  if (e.key === 'End') { e.preventDefault(); readAt(SV.s.T); return; }
  if (!d) return; e.preventDefault(); readAt((surT < 0 ? 0 : surT) + d);
});
stepBtns.forEach((btn) => btn.addEventListener('click', () => step(+btn.dataset.step)));

/* ------------------------------------------------------------ levers */
const sliders = $$('[data-lever]'), outs = $$('[data-out]'), resultEl = $('[data-result]');
const resetBtn = $('[data-reset]'), saveBtn = $('[data-save]'), savedEl = $('[data-saved]');
const key = () => L.map((v) => Math.round(v * 100)).join('/');
function leverState() {
  const any = L.some((v) => v > 0);
  resetBtn.disabled = !any; resetBtn.title = any ? 'Set every lever back to zero' : 'All levers are already at zero';
  const dup = saved.some((s) => s.key === key());
  saveBtn.disabled = !any || dup;
  saveBtn.title = !any ? 'Move a lever first — there is nothing to save' : dup ? 'This scenario is already saved' : 'Keep this scenario to compare later';
  $$('button', savedEl).forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.key === key())));
  if (!any) { resultEl.classList.remove('on'); resultEl.innerHTML = 'Move a lever to model the subscribers it would keep.'; return; }
  const dSubs = ACF.tot[LAST] - A.tot[LAST], dRev = ACF.rev[LAST] - A.rev[LAST];
  resultEl.classList.add('on');
  resultEl.innerHTML = 'Keeps <b>+' + fmt(dSubs) + '</b> more subscribers by Sep 2026 — about <b>+$' + (dRev / 1000).toFixed(dRev < 10000 ? 1 : 0) + 'k</b> a year in revenue, in this view.';
}
function applyLevers(vals, quiet) {
  L = vals.slice();
  sliders.forEach((s, i) => { s.value = Math.round(L[i] * 100); outs[i].textContent = Math.round(L[i] * 100) + '%'; });
  CF = L.some((v) => v > 0) ? simulate(L) : BASE;
  ACF = agg(CF);
  renderChart(true); leverState();
  if (!quiet) kpis();
}
sliders.forEach((s, i) => s.addEventListener('input', () => { const v = L.slice(); v[i] = +s.value / 100; applyLevers(v); }));
resetBtn.addEventListener('click', () => { applyLevers([0, 0, 0]); toast('Levers reset — showing actual retention'); });
saveBtn.addEventListener('click', () => {
  const k = key(), d = ACF.tot[LAST] - A.tot[LAST];
  saved.push({ key: k, L: L.slice(), d });
  const li = document.createElement('li');
  li.innerHTML = '<button type="button" aria-pressed="true" data-key="' + k + '">' + k.split('/').map((v, i) => ['Onb ', 'Intro ', 'Renew '][i] + v).join(' · ') + ' <b>+' + fmt(d) + '</b></button>';
  savedEl.appendChild(li);
  leverState();
  toast('Scenario saved: +' + fmt(d) + ' subscribers by Sep 2026');
});
savedEl.addEventListener('click', (e) => {
  const b = e.target.closest('button[data-key]'); if (!b) return;
  const s = saved.find((x) => x.key === b.dataset.key); if (!s) return;
  if (b.dataset.key === key()) { applyLevers([0, 0, 0]); toast('Scenario cleared'); }
  else { applyLevers(s.L); toast('Scenario applied'); }
});

/* ------------------------------------------------------------ table */
const tbody = $('[data-tbody]');
function retAt(b, t) { const c = b - 1; return c + t <= LAST && A.joined[b] ? A.v[b][c + t] / A.joined[b] : null; }
function renderTable() {
  const rows = [];
  for (let b = 1; b < A.v.length; b++) {
    if (!A.joined[b]) continue;
    if (b - 1 < (range === 18 ? 0 : 6)) continue;
    rows.push({ b, c: b - 1, n: A.joined[b], r1: retAt(b, 1), r3: retAt(b, 3), r6: retAt(b, 6), r12: retAt(b, 12), a: A.v[b][LAST] });
  }
  rows.sort((p, q) => {
    const a = p[sort.k], z = q[sort.k];
    if (a == null && z == null) return p.c - q.c;
    if (a == null) return 1; if (z == null) return -1;
    return (a - z) * sort.dir || p.c - q.c;
  });
  const cell = (v, i) => (v == null ? '<span class="dmp-churn__cell na">—</span>' : '<span class="dmp-churn__cell" style="--v:' + v.toFixed(3) + ';--r:' + i + '">' + (v * 100).toFixed(1) + '%<i></i></span>');
  tbody.innerHTML = rows.map((r, i) => {
    const mx = A.mix[r.b], lead = mx.intro / r.n > 0.4 ? 'intro deal ' + pct(mx.intro, r.n, 0) : mx.student / r.n > 0.4 ? 'student ' + pct(mx.student, r.n, 0) : 'monthly ' + pct(mx.monthly, r.n, 0);
    return '<tr data-b="' + r.b + '" aria-selected="' + (r.b === sel) + '" tabindex="' + (r.b === sel ? 0 : -1) + '"><td>' + mLabel(r.c) + '<small>' + lead + '</small></td><td>' + fmt(r.n) + '</td><td>' + cell(r.r1, i) + '</td><td>' + cell(r.r3, i) + '</td><td>' + cell(r.r6, i) + '</td><td>' + cell(r.r12, i) + '</td><td>' + fmt(r.a) + '</td></tr>';
  }).join('');
  if (!tbody.querySelector('[tabindex="0"]') && tbody.firstElementChild) tbody.firstElementChild.tabIndex = 0;
  $$('thead th', root).forEach((th) => { const k = th.querySelector('button').dataset.sort; th.setAttribute('aria-sort', k === sort.k ? (sort.dir > 0 ? 'ascending' : 'descending') : 'none'); });
}
$('thead', root).addEventListener('click', (e) => {
  const b = e.target.closest('button[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  sort = { k, dir: sort.k === k ? -sort.dir : (k === 'c' ? 1 : -1) };
  renderTable();
});
tbody.addEventListener('click', (e) => { const tr = e.target.closest('tr[data-b]'); if (tr && +tr.dataset.b !== sel) select(+tr.dataset.b); });
tbody.addEventListener('keydown', (e) => {
  const tr = e.target.closest('tr[data-b]'); if (!tr) return;
  let n = null;
  if (e.key === 'ArrowDown') n = tr.nextElementSibling; else if (e.key === 'ArrowUp') n = tr.previousElementSibling;
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(+tr.dataset.b); tr.focus(); return; }
  if (n) { e.preventDefault(); select(+n.dataset.b); n.focus(); }
});

/* ------------------------------------------------------------ KPIs */
function kpis() {
  const rs = range === 18 ? 0 : 6, start = A.tot[rs], end = A.tot[LAST];
  let nw = 0, lost = 0; for (let b = 1; b < A.v.length; b++) if (b - 1 > rs) nw += A.joined[b];
  for (let b = 0; b < A.v.length; b++) for (let k = rs + 1; k < N; k++) lost += A.lost[b][k];
  let n3 = 0, d3 = 0, n1 = 0, d1 = 0;
  for (let b = 1; b < A.v.length; b++) { const c = b - 1; if (c < rs || !A.joined[b]) continue; if (c + 3 <= LAST) { n3 += A.v[b][c + 3]; d3 += A.joined[b]; } if (c + 1 <= LAST) { n1 += A.v[b][c + 1]; d1 += A.joined[b]; } }
  let rate = 0, cnt = 0; for (let k = rs + 1; k < N; k++) { let l = 0; for (let b = 0; b < A.v.length; b++) l += A.lost[b][k]; if (A.tot[k - 1]) { rate += l / A.tot[k - 1]; cnt++; } }
  tweenTo('end', end, fmt); $('[data-ks="end"]').textContent = (end >= start ? '+' : '−') + fmt(Math.abs(end - start)) + ' since ' + mLabel(rs);
  tweenTo('new', nw, (v) => '+' + fmt(v)); $('[data-ks="new"]').textContent = 'on top of ' + fmt(start) + ' in ' + MON[rs];
  tweenTo('lost', lost, (v) => '−' + fmt(v)); $('[data-ks="lost"]').textContent = (cnt ? (rate / cnt * 100).toFixed(1) : '0.0') + '% a month';
  tweenTo('m3', d3 ? n3 / d3 * 100 : 0, (v) => v.toFixed(1) + '%'); $('[data-ks="m3"]').textContent = 'M1 ' + (d1 ? (n1 / d1 * 100).toFixed(1) : '—') + '%';
}

/* ------------------------------------------------------------ filters, tabs, refresh */
function gate() {
  const studentBtn = $('[data-plan] [data-v="student"]'), introBtn = $('[data-offer] [data-v="intro"]');
  const sOff = offer === 'intro', iOff = plan === 'student';
  studentBtn.setAttribute('aria-disabled', String(sOff)); studentBtn.title = sOff ? 'Student plans are never sold on an intro deal' : '';
  introBtn.setAttribute('aria-disabled', String(iOff)); introBtn.title = iOff ? 'Student plans are never sold on an intro deal' : '';
}
function refresh(animate) {
  A = agg(BASE); ACF = L.some((v) => v > 0) ? agg(CF) : A;
  renderChart(animate); renderSide(); renderTable(); kpis(); leverState(); gate();
}
radios($('[data-plan]'), (v) => { plan = v; refresh(true); });
radios($('[data-offer]'), (v) => { offer = v; refresh(true); });
radios($('[data-range]'), (v) => { range = +v; refresh(true); });
const tabs = $$('[role="tab"]');
function setView(v) {
  view = v;
  tabs.forEach((t) => { const on = t.dataset.view === v; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; });
  $$('[data-panel]').forEach((p) => { p.hidden = p.dataset.panel !== v; });
  if (v === 'cake') renderChart(false); else renderTable();
}
$('[data-tabs]').addEventListener('click', (e) => { const t = e.target.closest('[role="tab"]'); if (t && t.getAttribute('aria-selected') !== 'true') setView(t.dataset.view); });
$('[data-tabs]').addEventListener('keydown', (e) => {
  const i = tabs.indexOf(document.activeElement); if (i < 0) return;
  const d = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0; if (!d) return;
  e.preventDefault(); const t = tabs[(i + d + tabs.length) % tabs.length]; t.focus(); setView(t.dataset.view);
});

/* ------------------------------------------------------------ boot + resize */
refresh(false);
let rq = 0;
const ro = new ResizeObserver(() => {
  if (rq) return;
  rq = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    rq = 0;
    if (view === 'cake') renderChart(false);
    if (SV) { const t = surT; drawSurvival(survival(sel)); if (t >= 0) readAt(t); }
  });
});
ro.observe(chart); ro.observe(surv);

css:
.dmp-letters {
  /* re-theme with these four */
  --dmp-letters-bg: oklch(0.974 0.01 95);
  --dmp-letters-ink: oklch(0.24 0.03 165);
  --dmp-letters-gain: oklch(0.52 0.1 168);
  --dmp-letters-loss: oklch(0.6 0.17 32);

  --dmp-letters-card: color-mix(in oklch, var(--dmp-letters-bg) 35%, white);
  --dmp-letters-side: color-mix(in oklch, var(--dmp-letters-bg) 92%, var(--dmp-letters-gain));
  --dmp-letters-line: color-mix(in oklch, var(--dmp-letters-ink) 13%, transparent);
  --dmp-letters-hair: color-mix(in oklch, var(--dmp-letters-ink) 7%, transparent);
  --dmp-letters-soft: color-mix(in oklch, var(--dmp-letters-ink) 4%, transparent);
  --dmp-letters-mute: color-mix(in oklch, var(--dmp-letters-ink) 66%, var(--dmp-letters-bg));
  --dmp-letters-faint: color-mix(in oklch, var(--dmp-letters-ink) 46%, var(--dmp-letters-bg));
  --dmp-letters-s0: var(--dmp-letters-gain);
  --dmp-letters-s1: color-mix(in oklch, var(--dmp-letters-gain) 60%, oklch(0.78 0.14 140));
  --dmp-letters-s2: color-mix(in oklch, var(--dmp-letters-gain) 25%, oklch(0.86 0.1 128));
  --dmp-letters-s3: oklch(0.79 0.13 86);
  --dmp-letters-s4: var(--dmp-letters-loss);
  --dmp-letters-s5: color-mix(in oklch, var(--dmp-letters-loss) 45%, oklch(0.8 0.1 60));
  --dmp-letters-s6: color-mix(in oklch, var(--dmp-letters-loss) 65%, oklch(0.32 0.08 25));
  --dmp-letters-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dmp-letters-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dmp-letters-out: cubic-bezier(.16, 1, .3, 1);
  --dmp-letters-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);

  width: 100%;
  height: var(--dmp-letters-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dmp-letters-bg);
  color: var(--dmp-letters-ink);
  font: 13px/1.45 var(--dmp-letters-sans);
  accent-color: var(--dmp-letters-gain);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dmp-letters-line);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dmp-letters-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, ol, dl, dd) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dmp-letters-gain); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}

.dmp-letters__shell { height: 100%; display: grid; grid-template: "side main" minmax(0, 1fr) / 216px minmax(0, 1fr); }

/* ---------- side */
.dmp-letters__side {
  grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 6px;
  padding: 16px 12px; background: var(--dmp-letters-side); border-right: 1px solid var(--dmp-letters-line);
}
.dmp-letters__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px 12px;
  & svg { width: 34px; height: 34px; padding: 6px; flex: none; border-radius: 10px; background: var(--dmp-letters-ink); fill: none; stroke: var(--dmp-letters-bg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dmp-letters-mute); }
}
.dmp-letters__lbl { padding: 0 6px; font-size: 10.5px; font-weight: 720; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-letters-faint); }
.dmp-letters__lists { display: grid; gap: 3px; }
.dmp-letters__opt {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; align-items: center;
  padding: 8px 9px 8px 11px; border-radius: 11px; cursor: pointer;
  transition: background-color .2s, box-shadow .2s;
  animation: dmp-letters-rise .55s var(--dmp-letters-out) both; animation-delay: calc(var(--i, 0) * 45ms + 60ms);
  & .nm { font-weight: 680; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .cd { grid-column: 1; font-size: 11px; color: var(--dmp-letters-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .sz { grid-row: 1; grid-column: 2; font: 650 11.5px var(--dmp-letters-mono); font-variant-numeric: tabular-nums; text-align: right; }
  & .dl { grid-column: 2; font: 600 10.5px var(--dmp-letters-mono); text-align: right; color: var(--dmp-letters-gain); font-variant-numeric: tabular-nums; }
  & .dl.neg { color: var(--dmp-letters-loss); }
  & svg { grid-column: 1 / -1; width: 100%; height: 18px; margin-top: 3px; overflow: visible; }
  & svg path { fill: none; stroke: color-mix(in oklch, var(--dmp-letters-ink) 35%, transparent); stroke-width: 1.3; stroke-linejoin: round; }
  & svg rect { fill: color-mix(in oklch, var(--dmp-letters-gain) 14%, transparent); transition: x .4s var(--dmp-letters-out), width .4s var(--dmp-letters-out); }
  &:hover { background: var(--dmp-letters-hair); }
  &[aria-selected="true"] {
    background: var(--dmp-letters-card); box-shadow: inset 0 0 0 1px var(--dmp-letters-line), 0 6px 16px -12px color-mix(in oklch, var(--dmp-letters-ink) 60%, transparent);
    & svg path { stroke: var(--dmp-letters-gain); }
    &::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 3px; background: var(--dmp-letters-gain); }
  }
}

/* ---------- main */
.dmp-letters__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 14px 16px 16px; }
.dmp-letters__head { display: flex; align-items: flex-end; justify-content: space-between; flex-wrap: wrap; gap: 8px 16px; }
.dmp-letters__eyebrow { font-size: 10.5px; font-weight: 720; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-letters-faint); font-variant-numeric: tabular-nums; }
.dmp-letters__head h2 { font-size: clamp(17px, 2.1cqi, 22px); font-weight: 780; letter-spacing: -.03em; line-height: 1.15; text-wrap: balance; }
.dmp-letters__tabs {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dmp-letters-hair);
  & button { padding: 6px 13px; border-radius: 8px; font-weight: 650; font-size: 12.5px; color: var(--dmp-letters-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dmp-letters-ink); }
  & button[aria-selected="true"] { background: var(--dmp-letters-card); color: var(--dmp-letters-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dmp-letters-ink) 18%, transparent), inset 0 0 0 1px var(--dmp-letters-line); }
}
.dmp-letters__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; margin: 0;
  border-radius: 13px; background: var(--dmp-letters-card); box-shadow: inset 0 0 0 1px var(--dmp-letters-line);
  & > div { padding: 9px 14px 10px; border-left: 1px solid var(--dmp-letters-hair); animation: dmp-letters-rise .6s var(--dmp-letters-out) both; animation-delay: calc(var(--i) * 55ms); }
  & > div:first-child { border-left: 0; }
  & dt { font-size: 11px; color: var(--dmp-letters-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 7px; }
  & b { font-size: clamp(18px, 2.1cqi, 23px); font-weight: 780; letter-spacing: -.035em; font-variant-numeric: tabular-nums; line-height: 1.15; }
  & small { font-size: 11px; color: var(--dmp-letters-mute); font-variant-numeric: tabular-nums; }
  & small.up { color: var(--dmp-letters-gain); font-weight: 650; }
  & small.down { color: var(--dmp-letters-loss); font-weight: 650; }
}

.dmp-letters__body {
  min-height: 0; display: grid; gap: 12px;
  grid-template: "chart ledger" minmax(0, 1fr) "brush ledger" auto / minmax(0, 1fr) 262px;
}
.dmp-letters__panel {
  position: relative; min-width: 0; min-height: 0; border-radius: 15px; background: var(--dmp-letters-card);
  box-shadow: inset 0 0 0 1px var(--dmp-letters-line), 0 16px 30px -28px color-mix(in oklch, var(--dmp-letters-ink) 70%, transparent);
  animation: dmp-letters-rise .7s var(--dmp-letters-out) both; animation-delay: calc(var(--i, 0) * 80ms + 120ms);
}
.dmp-letters__flowp, .dmp-letters__issuesp { grid-area: chart; display: flex; flex-direction: column; padding: 12px 14px 8px; }
.dmp-letters__ledger { grid-area: ledger; display: flex; flex-direction: column; padding: 12px 14px; overflow: auto; }
.dmp-letters__brushp { grid-area: brush; padding: 10px 14px 12px; }
.dmp-letters__ph {
  display: flex; align-items: baseline; justify-content: space-between; flex-wrap: wrap; gap: 4px 10px; margin-bottom: 6px;
  & h3 { font-size: 10.5px; font-weight: 720; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-letters-mute); }
  & p { font-size: 11px; color: var(--dmp-letters-faint); font-variant-numeric: tabular-nums; }
}
.dmp-letters__legend { display: flex; align-items: center; gap: 6px; & i.net { width: 16px; height: 2px; background: var(--dmp-letters-ink); border-radius: 1px; } }

/* ---------- flow chart */
.dmp-letters__chart { position: relative; flex: 1; min-height: 200px; cursor: crosshair; border-radius: 8px; }
.dmp-letters__chart svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.dmp-letters__grid {
  & line { stroke: var(--dmp-letters-hair); }
  & line.zero { stroke: color-mix(in oklch, var(--dmp-letters-ink) 40%, transparent); }
  & text { fill: var(--dmp-letters-faint); font: 500 10.5px var(--dmp-letters-mono); font-variant-numeric: tabular-nums; }
  & rect.hot { fill: var(--dmp-letters-soft); }
}
.dmp-letters__bars {
  & g { transform-box: view-box; }
  & rect { transition: opacity .25s, filter .2s; }
  & g.wk.on rect { filter: brightness(1.06) saturate(1.15); }
}
.dmp-letters__bars.enter g.wk { animation: dmp-letters-bar .7s var(--dmp-letters-spring) both; animation-delay: calc(var(--i) * 18ms + 250ms); }
.dmp-letters__net { fill: none; stroke: var(--dmp-letters-ink); stroke-width: 1.6; stroke-linejoin: round; transition: opacity .25s; }
.dmp-letters__dots circle { fill: var(--dmp-letters-card); stroke: var(--dmp-letters-ink); stroke-width: 1.5; }
.dmp-letters__chart[data-focus] :is(.dmp-letters__net, .dmp-letters__dots) { opacity: .25; }
.dmp-letters__bars.enter ~ :is(.dmp-letters__net, .dmp-letters__dots) { animation: dmp-letters-fade .6s var(--dmp-letters-out) .9s both; }
.dmp-letters__xax text { fill: var(--dmp-letters-faint); font: 500 10.5px var(--dmp-letters-mono); text-anchor: middle; & .yr { font-weight: 700; } }
.dmp-letters__tip {
  position: absolute; left: 0; top: 0; z-index: 4; width: 220px; padding: 10px 12px; border-radius: 11px; pointer-events: none;
  background: var(--dmp-letters-ink); color: var(--dmp-letters-bg); font-size: 12px; line-height: 1.4;
  box-shadow: 0 18px 32px -16px color-mix(in oklch, var(--dmp-letters-ink) 80%, transparent);
