css:
.dmp-planner {
  /* re-theme with these four */
  --dmp-planner-bg: oklch(0.966 0.009 78);
  --dmp-planner-ink: oklch(0.27 0.016 60);
  --dmp-planner-hi: oklch(0.83 0.15 86);
  --dmp-planner-alert: oklch(0.6 0.19 29);

  --dmp-planner-card: color-mix(in oklch, var(--dmp-planner-bg) 25%, white);
  --dmp-planner-rail: color-mix(in oklch, var(--dmp-planner-ink) 94%, var(--dmp-planner-hi));
  --dmp-planner-line: color-mix(in oklch, var(--dmp-planner-ink) 13%, transparent);
  --dmp-planner-hair: color-mix(in oklch, var(--dmp-planner-ink) 7%, transparent);
  --dmp-planner-soft: color-mix(in oklch, var(--dmp-planner-ink) 4%, transparent);
  --dmp-planner-mute: color-mix(in oklch, var(--dmp-planner-ink) 64%, var(--dmp-planner-bg));
  --dmp-planner-faint: color-mix(in oklch, var(--dmp-planner-ink) 44%, var(--dmp-planner-bg));
  --dmp-planner-pitch: oklch(0.8 0.018 80);
  --dmp-planner-draft: color-mix(in oklch, var(--dmp-planner-hi) 85%, oklch(0.7 0.14 60));
  --dmp-planner-edit: oklch(0.73 0.11 340);
  --dmp-planner-ready: oklch(0.68 0.12 158);
  --dmp-planner-live: color-mix(in oklch, var(--dmp-planner-ink) 45%, var(--dmp-planner-bg));
  --dmp-planner-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dmp-planner-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dmp-planner-out: cubic-bezier(.16, 1, .3, 1);
  --dmp-planner-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);

  width: 100%;
  height: var(--dmp-planner-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dmp-planner-bg);
  color: var(--dmp-planner-ink);
  font: 13px/1.4 var(--dmp-planner-sans);
  accent-color: var(--dmp-planner-ink);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dmp-planner-line);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dmp-planner-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, fieldset) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dmp-planner-ink); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}

.dmp-planner__shell {
  height: 100%; display: grid;
  grid-template: "rail head" auto "rail main" minmax(0, 1fr) / 68px minmax(0, 1fr);
}

/* ---------- rail */
.dmp-planner__rail {
  grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 8px;
  background: var(--dmp-planner-rail); color: var(--dmp-planner-bg);
}
.dmp-planner__logo {
  display: grid; place-items: center; width: 38px; height: 38px; margin-bottom: 10px; border-radius: 11px;
  background: var(--dmp-planner-hi); color: var(--dmp-planner-ink); font: 800 20px/1 ui-serif, Georgia, serif; font-style: italic;
}
.dmp-planner__nav {
  display: grid; justify-items: center; gap: 3px; width: 52px; padding: 8px 0 7px; border-radius: 12px;
  font-size: 10.5px; font-weight: 650; color: color-mix(in oklch, var(--dmp-planner-bg) 60%, transparent);
  transition: background-color .2s, color .2s;
  & svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { color: var(--dmp-planner-bg); background: color-mix(in oklch, var(--dmp-planner-bg) 8%, transparent); }
  &[aria-current="page"] { color: var(--dmp-planner-ink); background: var(--dmp-planner-bg); }
  &:focus-visible { outline-color: var(--dmp-planner-hi); }
}

/* ---------- head */
.dmp-planner__head { grid-area: head; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; padding: 14px 16px 10px; }
.dmp-planner__wk {
  display: flex; align-items: center; gap: 10px; margin-right: auto;
  & small { display: block; font-size: 10.5px; font-weight: 720; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-planner-faint); }
  & h2 { font-size: clamp(17px, 2.1cqi, 22px); font-weight: 780; letter-spacing: -.03em; line-height: 1.1; font-variant-numeric: tabular-nums; text-wrap: balance; }
}
.dmp-planner__ib {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; flex: none;
  background: var(--dmp-planner-card); box-shadow: inset 0 0 0 1px var(--dmp-planner-line);
  transition: background-color .2s, scale .25s var(--dmp-planner-spring);
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &:hover:not(:disabled) { background: var(--dmp-planner-hair); }
  &:active:not(:disabled) { scale: .92; }
  &:disabled { opacity: .35; cursor: not-allowed; }
}
.dmp-planner__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dmp-planner-hair);
  & button { padding: 5px 11px; border-radius: 7px; font-size: 12px; font-weight: 640; color: var(--dmp-planner-mute); white-space: nowrap; transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dmp-planner-ink); }
  & button[aria-checked="true"] { background: var(--dmp-planner-card); color: var(--dmp-planner-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dmp-planner-ink) 20%, transparent), inset 0 0 0 1px var(--dmp-planner-line); }
  & button[aria-disabled="true"] { opacity: .4; cursor: not-allowed; }
  &.sm { width: 100%; & button { flex: 1; padding: 5px 4px; text-align: center; } }
}
.dmp-planner__stats { display: flex; gap: 12px; font-size: 11.5px; color: var(--dmp-planner-mute); font-variant-numeric: tabular-nums; & b { color: var(--dmp-planner-ink); font-weight: 720; } }
.dmp-planner__clash {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 999px; font-size: 12px; font-weight: 700;
  color: var(--dmp-planner-alert); background: color-mix(in oklch, var(--dmp-planner-alert) 11%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dmp-planner-alert) 30%, transparent);
  transition: background-color .2s, scale .25s var(--dmp-planner-spring);
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--dmp-planner-alert) 18%, transparent); }
  &:disabled { color: var(--dmp-planner-ready); background: color-mix(in oklch, var(--dmp-planner-ready) 12%, transparent); box-shadow: none; cursor: default; }
}

/* ---------- main */
.dmp-planner__main { grid-area: main; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 226px; gap: 12px; padding: 0 16px 16px; }
.dmp-planner__board {
  position: relative; min-width: 0; min-height: 0; overflow: auto; border-radius: 14px; background: var(--dmp-planner-card);
  box-shadow: inset 0 0 0 1px var(--dmp-planner-line);
  animation: dmp-planner-rise .6s var(--dmp-planner-out) .08s both;
}

/* week grid: one grid, rows are subgrids so labels, cells and the header share columns */
.dmp-planner__grid { display: grid; grid-template-columns: 88px repeat(7, minmax(98px, 1fr)); min-width: 774px; }
.dmp-planner__row { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; border-bottom: 1px solid var(--dmp-planner-hair); }
.dmp-planner__row.hdr { position: sticky; top: 0; z-index: 3; background: var(--dmp-planner-card); border-bottom-color: var(--dmp-planner-line); }
.dmp-planner__day {
  padding: 9px 8px 7px; font-size: 11px; font-weight: 700; color: var(--dmp-planner-mute); letter-spacing: .02em;
  & b { display: block; font-size: 16px; color: var(--dmp-planner-ink); letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  &.past { color: var(--dmp-planner-faint); & b { color: var(--dmp-planner-faint); } }
  &.today b { width: fit-content; min-width: 26px; padding: 0 6px; margin-left: -6px; border-radius: 8px; text-align: center; background: var(--dmp-planner-hi); }
}
.dmp-planner__rl {
  position: sticky; left: 0; z-index: 2; display: flex; flex-direction: column; justify-content: flex-start; gap: 4px; padding: 10px 8px 10px 12px;
  background: var(--dmp-planner-card); border-right: 1px solid var(--dmp-planner-hair);
  & b { font-size: 12px; font-weight: 720; line-height: 1.2; text-wrap: balance; }
  & small { font-size: 10.5px; color: var(--dmp-planner-faint); font-variant-numeric: tabular-nums; }
  & .dmp-planner__av { margin-bottom: 2px; }
}
.dmp-planner__row.hdr .dmp-planner__rl { z-index: 4; }
.dmp-planner__cell {
  position: relative; display: flex; flex-direction: column; gap: 5px; min-height: 76px; padding: 6px 5px;
  border-left: 1px solid var(--dmp-planner-hair); transition: background-color .15s, box-shadow .15s;
  &.past { background: repeating-linear-gradient(135deg, transparent 0 6px, var(--dmp-planner-soft) 6px 7px); }
  &.wkend:not(.past) { background: var(--dmp-planner-soft); }
  &.today { box-shadow: inset 0 3px 0 -1px var(--dmp-planner-hi); }
  &.drop { background: color-mix(in oklch, var(--dmp-planner-hi) 26%, transparent); box-shadow: inset 0 0 0 2px var(--dmp-planner-ink); }
  &.nodrop { background: color-mix(in oklch, var(--dmp-planner-alert) 9%, transparent); }
}
.dmp-planner__row.un { border-bottom: 0; }
.dmp-planner__row.un .dmp-planner__cell { grid-column: 2 / -1; flex-direction: row; flex-wrap: wrap; align-content: flex-start; min-height: 70px; background: var(--dmp-planner-soft); }
.dmp-planner__row.un .dmp-planner__card { width: 150px; }
.dmp-planner__row.un .dmp-planner__cell:empty::before { content: "Drop a story here to unschedule it"; align-self: center; margin: auto; font-size: 11.5px; color: var(--dmp-planner-faint); }

/* pipeline */
.dmp-planner__pipe { display: grid; grid-template-columns: repeat(5, minmax(150px, 1fr)); min-width: 780px; min-height: 100%; }
.dmp-planner__col { display: flex; flex-direction: column; min-width: 0; border-left: 1px solid var(--dmp-planner-hair); &:first-child { border-left: 0; } }
.dmp-planner__colh {
  position: sticky; top: 0; z-index: 2; display: flex; align-items: center; gap: 7px; padding: 10px 10px 8px; background: var(--dmp-planner-card); border-bottom: 1px solid var(--dmp-planner-line);
  & i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); }
  & b { font-size: 12px; font-weight: 720; }
  & small { margin-left: auto; font: 600 11px var(--dmp-planner-mono); color: var(--dmp-planner-faint); font-variant-numeric: tabular-nums; }
}
.dmp-planner__col .dmp-planner__cell { flex: 1; border-left: 0; min-height: 120px; padding: 8px; gap: 6px; }

/* cards */
.dmp-planner__card {
  --c: var(--dmp-planner-pitch);
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr); gap: 3px; min-width: 0; padding: 6px 7px 6px 10px; border-radius: 9px; cursor: pointer; touch-action: none; user-select: none;
  container-type: inline-size;
  background: var(--dmp-planner-card); box-shadow: inset 0 0 0 1px var(--dmp-planner-line), 0 1px 2px color-mix(in oklch, var(--dmp-planner-ink) 8%, transparent);
  transition: box-shadow .2s, translate .2s var(--dmp-planner-out), opacity .2s, filter .2s;
  animation: dmp-planner-card .5s var(--dmp-planner-spring) both; animation-delay: calc(var(--i, 0) * 22ms + 120ms);
  &::before { content: ""; position: absolute; left: 3px; top: 6px; bottom: 6px; width: 3px; border-radius: 2px; background: var(--c); }
  & .tp { display: flex; align-items: center; gap: 5px; font: 600 10px var(--dmp-planner-mono); color: var(--dmp-planner-faint); font-variant-numeric: tabular-nums; }
  & .tp svg { width: 12px; height: 12px; margin-left: auto; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & h4 { font-size: 11.5px; font-weight: 650; line-height: 1.25; letter-spacing: -.005em; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-wrap: pretty; }
  & .ft { display: flex; align-items: center; gap: 5px; min-width: 0; font-size: 10.5px; color: var(--dmp-planner-mute); white-space: nowrap; }
  & .ft .wd { overflow: hidden; text-overflow: ellipsis; }
  & .st { margin-left: auto; flex: none; padding: 0 5px; border-radius: 5px; font-weight: 650; background: color-mix(in oklch, var(--c) 30%, transparent); color: color-mix(in oklch, var(--c) 40%, var(--dmp-planner-ink)); }
  &:hover { translate: 0 -1px; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dmp-planner-ink) 22%, transparent), 0 8px 16px -10px color-mix(in oklch, var(--dmp-planner-ink) 50%, transparent); }
  &[data-s="draft"] { --c: var(--dmp-planner-draft); }
  &[data-s="edit"] { --c: var(--dmp-planner-edit); }
  &[data-s="ready"] { --c: var(--dmp-planner-ready); }
  &[data-s="live"] { --c: var(--dmp-planner-live); background: color-mix(in oklch, var(--dmp-planner-card) 60%, var(--dmp-planner-bg)); & h4 { color: var(--dmp-planner-mute); } }
  &.sel { box-shadow: inset 0 0 0 2px var(--dmp-planner-ink), 0 10px 18px -12px color-mix(in oklch, var(--dmp-planner-ink) 60%, transparent); }
  &.clash::after { content: "!"; position: absolute; right: -5px; top: -5px; display: grid; place-items: center; width: 16px; height: 16px; border-radius: 50%; background: var(--dmp-planner-alert); color: white; font: 800 10px/1 var(--dmp-planner-sans); box-shadow: 0 0 0 2px var(--dmp-planner-card); }
  &.dim { opacity: .28; filter: grayscale(1); }
  &.lifted { opacity: .3; }
  &.moving { box-shadow: inset 0 0 0 2px var(--dmp-planner-ink), 0 0 0 4px color-mix(in oklch, var(--dmp-planner-hi) 70%, transparent); }
}
.dmp-planner__board.noanim .dmp-planner__card { animation: none; }
@container (max-width: 100px) {
  .dmp-planner__card .ft .wd { display: none; }
}
.dmp-planner__av {
  display: inline-grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; flex: none;
  font: 700 8.5px/1 var(--dmp-planner-sans); letter-spacing: .02em;
  background: oklch(0.88 0.07 var(--h)); color: oklch(0.36 0.09 var(--h));
}
.dmp-planner .dmp-planner__av { box-shadow: 0 0 0 1px color-mix(in oklch, var(--dmp-planner-ink) 8%, transparent); }

/* ghost while dragging */
.dmp-planner__ghost {
  position: absolute; left: 0; top: 0; z-index: 30; width: 0; pointer-events: none; opacity: 0;
  &.on { opacity: 1; }
  & .dmp-planner__card { rotate: -2.5deg; scale: 1.04; box-shadow: inset 0 0 0 1px var(--dmp-planner-line), 0 22px 34px -16px color-mix(in oklch, var(--dmp-planner-ink) 65%, transparent); animation: none; }
}

/* ---------- load */
.dmp-planner__load {
  min-height: 0; overflow: auto; padding: 12px 12px 12px; border-radius: 14px; background: var(--dmp-planner-card); box-shadow: inset 0 0 0 1px var(--dmp-planner-line);
  animation: dmp-planner-rise .6s var(--dmp-planner-out) .16s both;
}
.dmp-planner__lh { padding: 0 2px 8px; & h3 { font-size: 10.5px; font-weight: 720; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-planner-mute); } & p { font-size: 11px; color: var(--dmp-planner-faint); } }
.dmp-planner__ldays, .dmp-planner__cells { display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px; }
.dmp-planner__ldays { margin: 0 0 4px; padding: 0 48px 0 34px; & span { font: 600 9.5px var(--dmp-planner-mono); text-align: center; color: var(--dmp-planner-faint); } & span.today { color: var(--dmp-planner-ink); } }
.dmp-planner__people { display: grid; gap: 2px; }
.dmp-planner__person {
  display: grid; grid-template-columns: 22px minmax(0, 1fr) 36px; align-items: center; gap: 2px 8px; width: 100%; padding: 6px 4px; border-radius: 9px;
  transition: background-color .15s;
  & .nm { font-size: 12px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .nm small { font-weight: 500; color: var(--dmp-planner-faint); margin-left: 4px; }
  & .tot { grid-row: 1 / 3; grid-column: 3; text-align: right; font: 650 11px var(--dmp-planner-mono); font-variant-numeric: tabular-nums; }
  & .tot.over { color: var(--dmp-planner-alert); }
  & .dmp-planner__av { grid-row: 1 / 3; }
  & .dmp-planner__cells { grid-column: 2; }
  & .dmp-planner__cells i {
    height: 8px; border-radius: 2px; background: var(--dmp-planner-hair);
    transition: background-color .3s, scale .4s var(--dmp-planner-spring);
  }
  & .dmp-planner__cells i.ok { background: color-mix(in oklch, var(--dmp-planner-ready) calc(30% + var(--f, 0) * 40%), transparent); }
  & .dmp-planner__cells i.full { background: var(--dmp-planner-ready); }
  & .dmp-planner__cells i.over { background: var(--dmp-planner-alert); scale: 1 1.35; }
  &:hover { background: var(--dmp-planner-soft); }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--dmp-planner-hi) 30%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dmp-planner-ink) 20%, transparent); }
}
.dmp-planner__lkey {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; margin-top: 10px; font-size: 10.5px; color: var(--dmp-planner-faint);
  & i { width: 10px; height: 7px; border-radius: 2px; margin-left: 4px; }
  & i.ok { background: color-mix(in oklch, var(--dmp-planner-ready) 45%, transparent); }
  & i.full { background: var(--dmp-planner-ready); }
  & i.over { background: var(--dmp-planner-alert); }
}

/* ---------- drawer */
.dmp-planner__drawer {
  position: absolute; top: 10px; right: 10px; bottom: 10px; z-index: 20; width: min(330px, calc(100% - 20px));
  display: flex; flex-direction: column; gap: 12px; padding: 14px 16px 16px; overflow: auto; border-radius: 16px;
  background: var(--dmp-planner-card); box-shadow: inset 0 0 0 1px var(--dmp-planner-line), 0 30px 60px -24px color-mix(in oklch, var(--dmp-planner-ink) 55%, transparent);
  translate: calc(100% + 24px) 0; visibility: hidden;
  transition: translate .5s var(--dmp-planner-spring), visibility 0s linear .5s;
  &.open { translate: 0 0; visibility: visible; transition: translate .5s var(--dmp-planner-spring), visibility 0s; }
}
.dmp-planner__dh { display: flex; align-items: center; justify-content: space-between; }
.dmp-planner__chip { padding: 3px 9px; border-radius: 999px; font-size: 11px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; background: var(--dmp-planner-hair); }
.dmp-planner__dt { font-size: 18px; font-weight: 780; letter-spacing: -.025em; line-height: 1.2; text-wrap: balance; }
.dmp-planner__dm { font-size: 12px; color: var(--dmp-planner-mute); text-wrap: pretty; font-variant-numeric: tabular-nums; & b { color: var(--dmp-planner-ink); } }
.dmp-planner__warn { padding: 8px 10px; border-radius: 10px; font-size: 12px; line-height: 1.4; color: color-mix(in oklch, var(--dmp-planner-alert) 70%, var(--dmp-planner-ink)); background: color-mix(in oklch, var(--dmp-planner-alert) 10%, transparent); text-wrap: pretty; }
.dmp-planner__form { display: grid; gap: 11px; &:disabled { opacity: .55; } }
.dmp-planner__field {
  display: grid; gap: 4px;
  & > span { font-size: 10.5px; font-weight: 720; letter-spacing: .1em; text-transform: uppercase; color: var(--dmp-planner-faint); }
  & select { width: 100%; padding: 7px 9px; border: 0; border-radius: 9px; font: inherit; color: inherit; background: var(--dmp-planner-soft); box-shadow: inset 0 0 0 1px var(--dmp-planner-line); cursor: pointer; }
}
.dmp-planner__two { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.dmp-planner__checks {
  display: grid; gap: 5px;
  & > span { font-size: 10.5px; font-weight: 720; letter-spacing: .1em; text-transform: uppercase; color: var(--dmp-planner-faint); }
  & label { display: flex; align-items: center; gap: 8px; padding: 5px 8px; border-radius: 8px; font-size: 12.5px; cursor: pointer; transition: background-color .15s; }
  & label:hover { background: var(--dmp-planner-soft); }
  & label:has(:checked) { color: var(--dmp-planner-mute); text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--dmp-planner-ink) 35%, transparent); }
  & input { width: 15px; height: 15px; margin: 0; }
}
.dmp-planner__btn {
  padding: 8px 12px; border-radius: 10px; font-size: 12.5px; font-weight: 680; text-align: center;
  background: var(--dmp-planner-soft); box-shadow: inset 0 0 0 1px var(--dmp-planner-line); transition: background-color .2s;
  &:hover:not(:disabled) { background: var(--dmp-planner-hair); }
  &:disabled { opacity: .45; cursor: not-allowed; }
}

.dmp-planner__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.dmp-planner__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 40; max-width: calc(100% - 32px); padding: 9px 14px; border-radius: 11px;
  background: var(--dmp-planner-ink); color: var(--dmp-planner-bg); font-size: 12.5px; font-weight: 600; text-wrap: pretty; pointer-events: none;
  opacity: 0; translate: -50% 10px; transition: opacity .2s, translate .35s var(--dmp-planner-out);
  &.on { opacity: 1; translate: -50% 0; }
}

@keyframes dmp-planner-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dmp-planner-card { from { opacity: 0; transform: translateY(6px) scale(.96); } }

@container (max-width: 1000px) {
  .dmp-planner__main { grid-template-columns: minmax(0, 1fr) 214px; }
  .dmp-planner__stats { display: none; }
}
/* narrow: the rail becomes a top bar, the load panel stacks under the board */
@container (max-width: 760px) {
  .dmp-planner__shell { grid-template: "rail" auto "head" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
  .dmp-planner__rail { flex-direction: row; padding: 8px 12px; gap: 4px; }
  .dmp-planner__logo { width: 32px; height: 32px; margin: 0 8px 0 0; font-size: 17px; }
  .dmp-planner__nav { grid-auto-flow: column; width: auto; gap: 6px; padding: 7px 11px; font-size: 12px; & svg { width: 17px; height: 17px; } }
  .dmp-planner__head { padding: 10px 12px 8px; }
  .dmp-planner__main { display: flex; flex-direction: column; overflow: auto; overscroll-behavior: contain; padding: 0 12px 12px; & > * { flex: none; } }
  .dmp-planner__board { height: 380px; }
  .dmp-planner__load { overflow: visible; }
}
@container (max-width: 440px) {
  .dmp-planner__wk h2 { font-size: 16px; }
  .dmp-planner__clash span { display: none; }
  .dmp-planner__clash { padding: 7px; }
}

@media (prefers-reduced-motion: reduce) {
  .dmp-planner :is(.dmp-planner__board, .dmp-planner__load, .dmp-planner__card) { animation: none; }
  .dmp-planner__drawer, .dmp-planner__drawer.open { transition: visibility 0s, opacity .2s; }
  .dmp-planner__card:hover { translate: 0 0; }
  .dmp-planner__person .dmp-planner__cells i { transition: background-color .2s; }
  .dmp-planner__ghost .dmp-planner__card { rotate: 0deg; scale: 1; }
  .dmp-planner__toast { transition: opacity .2s; translate: -50% 0; }
}

