  Object.values(seen).forEach((g) => { if (g.length > 1) out.push({ ids: g.map((c) => c.id), text: g.length + ' ' + DBY[g[0].desk].n + ' stories share ' + DAYN[g[0].day] + ' ' + g[0].slot + '. Move one to a free slot.' }); });
