css:
@property --dmp-listen-p { syntax: "<number>"; inherits: false; initial-value: 0; }

.dmp-listen {
  /* re-theme with these four */
  --dmp-listen-bg: oklch(0.195 0.022 335);
  --dmp-listen-ink: oklch(0.95 0.012 60);
  --dmp-listen-hi: oklch(0.82 0.15 70);
  --dmp-listen-loss: oklch(0.7 0.16 22);

  --dmp-listen-panel: color-mix(in oklch, var(--dmp-listen-bg) 92%, var(--dmp-listen-ink));
  --dmp-listen-side: color-mix(in oklch, var(--dmp-listen-bg) 82%, black);
  --dmp-listen-line: color-mix(in oklch, var(--dmp-listen-ink) 12%, transparent);
  --dmp-listen-hair: color-mix(in oklch, var(--dmp-listen-ink) 6%, transparent);
  --dmp-listen-mute: color-mix(in oklch, var(--dmp-listen-ink) 66%, var(--dmp-listen-bg));
  --dmp-listen-faint: color-mix(in oklch, var(--dmp-listen-ink) 42%, var(--dmp-listen-bg));
  --dmp-listen-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dmp-listen-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dmp-listen-out: cubic-bezier(.16, 1, .3, 1);
  --dmp-listen-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001);

  width: 100%;
  height: var(--dmp-listen-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dmp-listen-bg);
  color: var(--dmp-listen-ink);
  font: 13px/1.45 var(--dmp-listen-sans);
  accent-color: var(--dmp-listen-hi);
  color-scheme: dark;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dmp-listen-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dmp-listen-hi); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}
.dmp-listen__shell { height: 100%; display: grid; grid-template: "side main" minmax(0, 1fr) / 252px minmax(0, 1fr); }

/* ---------- episodes */
.dmp-listen__side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 16px 12px 12px; background: var(--dmp-listen-side); border-right: 1px solid var(--dmp-listen-line); }
.dmp-listen__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px 4px;
  & svg { width: 34px; height: 34px; padding: 6px; flex: none; border-radius: 10px; background: var(--dmp-listen-hi); fill: none; stroke: var(--dmp-listen-bg); stroke-width: 2; stroke-linecap: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dmp-listen-mute); }
}
.dmp-listen__tabs {
  display: grid; grid-template-columns: 1fr 1fr; padding: 3px; border-radius: 11px; background: var(--dmp-listen-hair); box-shadow: inset 0 0 0 1px var(--dmp-listen-line);
  & button { display: flex; align-items: center; justify-content: center; gap: 6px; padding: 6px 8px; border-radius: 8px; font-size: 12.5px; font-weight: 650; color: var(--dmp-listen-mute); transition: background-color .2s, color .2s; }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & button:hover { color: var(--dmp-listen-ink); }
  & button[aria-selected="true"] { background: var(--dmp-listen-ink); color: var(--dmp-listen-bg); }
}
.dmp-listen__show { padding: 2px 6px 0; font-size: 10.5px; font-weight: 720; letter-spacing: .12em; text-transform: uppercase; color: var(--dmp-listen-faint); }
.dmp-listen__eps { flex: 1; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 2px; margin: 0 -4px; padding: 0 4px; }
.dmp-listen__ep {
  display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 1px 10px; align-items: center; padding: 8px 8px; border-radius: 11px; cursor: pointer;
  transition: background-color .2s;
  animation: dmp-listen-rise .5s var(--dmp-listen-out) both; animation-delay: calc(var(--i, 0) * 45ms + 80ms);
  & .ring {
    grid-row: 1 / 3; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%;
    font: 700 9.5px var(--dmp-listen-mono); font-variant-numeric: tabular-nums;
