  --dmp-yield-mute: color-mix(in oklch, var(--dmp-yield-ink) 64%, var(--dmp-yield-bg));
  --dmp-yield-faint: color-mix(in oklch, var(--dmp-yield-ink) 44%, var(--dmp-yield-bg));
  --dmp-yield-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
