.dmp-yield__mapp { grid-area: map; display: flex; flex-direction: column; padding: 12px 12px 10px; }
.dmp-yield__lab { grid-area: lab; display: flex; flex-direction: column; padding: 12px 14px 10px; }
.dmp-yield__tablep { grid-area: table; max-height: 232px; overflow: auto; }

/* ---------- page template */
.dmp-yield__mapwrap { flex: 1; min-height: 0; overflow: auto; margin: 0 -4px; padding: 2px 4px 6px; border-radius: 10px; }
.dmp-yield__page {
  position: relative; display: grid; gap: 6px; padding: 8px; border-radius: 10px;
  background: var(--dmp-yield-bg); box-shadow: inset 0 0 0 1px var(--dmp-yield-line);
  & .nav { height: 10px; border-radius: 3px; background: var(--dmp-yield-ink); }
