  & .col { display: grid; gap: 6px; align-content: start; }
  & .rail { position: sticky; top: 4px; }
  & .t { height: 7px; border-radius: 2px; background: color-mix(in oklch, var(--dmp-yield-ink) 70%, transparent); }
  & .t.s { width: 72%; }
  & .by { height: 4px; width: 40%; border-radius: 2px; background: var(--dmp-yield-line); }
  & .img { height: 58px; border-radius: 4px; background: repeating-linear-gradient(135deg, var(--dmp-yield-hair) 0 5px, transparent 5px 10px), var(--dmp-yield-soft); }
  & .p { display: grid; gap: 3px; }
  & .p i { height: 3px; border-radius: 2px; background: var(--dmp-yield-line); }
  & .p i:last-child { width: 64%; }
  & .ml i { height: 3px; border-radius: 2px; background: var(--dmp-yield-line); display: block; margin-top: 5px; }
  &.mobile { width: 168px; margin-inline: auto; padding: 8px 8px 30px; border-radius: 18px; box-shadow: inset 0 0 0 1px var(--dmp-yield-line), 0 0 0 5px var(--dmp-yield-soft); }
