  & text { font: 650 10px var(--dmp-yield-sans); fill: var(--dmp-yield-ink); paint-order: stroke; stroke: var(--dmp-yield-card); stroke-width: 3px; stroke-linejoin: round; }
  & text.g { fill: color-mix(in oklch, var(--dmp-yield-good) 75%, var(--dmp-yield-ink)); }
  & .cur circle { fill: var(--dmp-yield-hot); stroke: var(--dmp-yield-card); stroke-width: 2; }
}
.dmp-yield__drag { position: absolute; inset: 0; z-index: 1; cursor: ew-resize; touch-action: none; }
.dmp-yield__floor {
  position: absolute; left: 0; top: 4px; bottom: 22px; z-index: 2; width: 18px; margin-left: -9px; cursor: ew-resize; touch-action: none;
