  & tfoot td { position: sticky; bottom: 0; background: var(--dmp-yield-card); border-top: 1px solid var(--dmp-yield-line); border-bottom: 0; font-weight: 760; }
}

.dmp-yield__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 9; max-width: calc(100% - 32px); padding: 9px 14px; border-radius: 11px;
  background: var(--dmp-yield-ink); color: var(--dmp-yield-bg); font-size: 12.5px; font-weight: 600; text-wrap: pretty; pointer-events: none;
  opacity: 0; translate: -50% 10px; transition: opacity .2s, translate .35s var(--dmp-yield-out);
  &.on { opacity: 1; translate: -50% 0; }
}

@keyframes dmp-yield-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dmp-yield-grow { from { transform: scaleY(0); } }
@keyframes dmp-yield-draw { from { stroke-dashoffset: var(--len, 3000); } }
@keyframes dmp-yield-slot { from { opacity: .35; transform: scale(.94); } }

@container (max-width: 1000px) {
  .dmp-yield__body { grid-template-columns: 250px minmax(0, 1fr); }
  .dmp-yield__table :is(th, td):nth-child(4) { display: none; }
}
@container (max-width: 760px) {
  .dmp-yield__shell { padding: 12px; gap: 10px; }
  .dmp-yield__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .dmp-yield__body { display: flex; flex-direction: column; overflow: auto; overscroll-behavior: contain; & > * { flex: none; } }
  .dmp-yield__mapp { height: 380px; }
  .dmp-yield__lab { height: 340px; }
  .dmp-yield__tablep { max-height: none; overflow-x: auto; }
}
@container (max-width: 440px) {
  .dmp-yield__brand small { display: none; }
  .dmp-yield__kpis small { display: none; }
  .dmp-yield__table :is(th, td):nth-child(3) { display: none; }
  .dmp-yield__legend { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dmp-yield :is(.dmp-yield__kpis > div, .dmp-yield__panel, .dmp-yield__hist.enter rect, .dmp-yield__curve.enter) { animation: none; }
  .dmp-yield__mapwrap .dmp-yield__slot { animation: none; }
  .dmp-yield__slot { transition: background-color .2s, color .2s; }
  .dmp-yield__slot:hover { scale: 1; }
  .dmp-yield__toast { transition: opacity .2s; translate: -50% 0; }
}

