    { id: 'ia3', n: 'In-article 3', sz: '300×250', ipv: 0.44, view: 0.51, m: 0.95, s: 0.78, q: 0.18, f: 0.5, h: 66 },
    { id: 'ft', n: 'Footer', sz: '728×90', ipv: 0.31, view: 0.39, m: 0.55, s: 0.8, q: 0.3, f: 0.5, h: 24 }
  ],
  mobile: [
    { id: 'top', n: 'Top banner', sz: '320×50', ipv: 1.0, view: 0.52, m: 0.6, s: 0.7, q: 0.1, f: 0.3, h: 22 },
    { id: 'ia1', n: 'In-article 1', sz: '300×250', ipv: 0.89, view: 0.71, m: 1.3, s: 0.68, q: 0.07, f: 0.5, h: 92 },
