  P.A.forEach((a, i) => { a.shown = a.shown || {}; a.shown[m.id] = shown[i]; });
}));

/* ------------------------------------------------------------ state */
let period = 30, model = 'linear', desk = 'all', sort = { k: 'credit', dir: -1 }, sel = 'tr', prevRank = null;
const D_ = () => PERIODS[period];
const au = (id) => D_().A.find((a) => a.id === id);
const visible = (a) => desk === 'all' || a.desk === desk;
const per100k = (a) => a.credit[model] / a.pv * 1e5;
const deskColor = (d) => 'var(--dmp-bylines-' + d + ')';
const initials = (n) => n.split(' ').map((x) => x[0]).join('');

/* ------------------------------------------------------------ desk chips */
const desksEl = $('[data-desks]');
desksEl.innerHTML = '<button type="button" role="radio" aria-checked="true" data-v="all"><i style="--c:var(--dmp-bylines-ink)"></i>All desks<small data-dc="all"></small></button>' +
  DESKS.map((d) => '<button type="button" role="radio" aria-checked="false" tabindex="-1" data-v="' + d.id + '"><i style="--c:' + deskColor(d.id) + '"></i>' + d.n + '<small data-dc="' + d.id + '"></small></button>').join('');

/* ------------------------------------------------------------ leaderboard rows (persistent nodes, FLIP on reorder) */
const rowsEl = $('[data-rows]'), rowNode = {};
RAW.forEach((a, i) => {
  const li = document.createElement('li');
  li.className = 'dmp-bylines__row'; li.setAttribute('role', 'option'); li.dataset.id = a[0]; li.style.setProperty('--i', i); li.style.setProperty('--c', deskColor(a[2]));
  li.innerHTML = '<span class="rk"><span data-r></span><small data-rc></small></span><span class="au"><span class="av">' + initials(a[1]) + '</span><span><b>' + a[1] + '</b><small>' + DN[a[2]] + '</small></span></span>' +
    '<span class="st" data-st></span><span class="pv" data-pv></span><span class="en" data-en></span><span class="cr"><i data-bar></i><b data-cr></b></span>';
  rowNode[a[0]] = li; rowsEl.appendChild(li);
});
function ranks() { const vis = D_().A.filter(visible).sort((a, b) => b.credit[model] - a.credit[model]); const m = {}; vis.forEach((a, i) => { m[a.id] = i + 1; }); return m; }
function renderRows(flip) {
  const D = D_(), rk = ranks(), maxC = Math.max(...D.A.filter(visible).map((a) => a.credit[model]));
  const key = { name: (a) => a.name, stories: (a) => a.stories, pv: (a) => a.pv, eng: (a) => a.eng, credit: (a) => a.credit[model] }[sort.k];
  const order = D.A.slice().sort((a, b) => { const p = key(a), q = key(b); return (p < q ? -1 : p > q ? 1 : 0) * sort.dir || a.i - b.i; });
  const before = new Map();
  if (flip && !RM) Object.values(rowNode).forEach((n) => { if (n.offsetParent) before.set(n, n.getBoundingClientRect().top); });
  order.forEach((a) => {
    const n = rowNode[a.id], vis = visible(a);
    n.classList.toggle('out', !vis);
    n.querySelector('[data-r]').textContent = vis ? rk[a.id] : '';
    const rc = n.querySelector('[data-rc]'), d = prevRank && prevRank[a.id] && vis ? prevRank[a.id] - rk[a.id] : 0;
    rc.textContent = d > 0 ? '▲' + d : d < 0 ? '▼' + -d : ''; rc.className = d > 0 ? 'up' : d < 0 ? 'dn' : '';
    n.querySelector('[data-st]').textContent = a.stories;
    n.querySelector('[data-pv]').textContent = kfmt(a.pv);
    n.querySelector('[data-en]').textContent = mmss(a.eng);
    n.querySelector('[data-bar]').style.setProperty('--v', (a.credit[model] / maxC).toFixed(3));
    n.querySelector('[data-cr]').textContent = a.shown[model].toFixed(1);
    n.setAttribute('aria-selected', String(a.id === sel)); n.tabIndex = a.id === sel ? 0 : -1;
    n.setAttribute('aria-label', a.name + ', ' + DN[a.desk] + ', rank ' + (rk[a.id] || '–') + ', ' + a.shown[model].toFixed(1) + ' subscribers credited');
    rowsEl.appendChild(n);
  });
  if (flip && !RM) before.forEach((top, n) => {
    if (!n.offsetParent) return;
    const dy = top - n.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) n.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.2,.9,.25,1.08)' });
  });
  Object.values(rowNode).forEach((n) => { if (n.offsetParent && !before.has(n) && flip && !RM) n.animate([{ opacity: 0, transform: 'translateX(-8px)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.16,1,.3,1)' }); });
  $$('[data-thead] [aria-sort]').forEach((h) => { const k = h.querySelector('button').dataset.sort; h.setAttribute('aria-sort', k === sort.k ? (sort.dir > 0 ? 'ascending' : 'descending') : 'none'); });
  /* footer: credit is conserved */
  const vis = D.A.filter(visible), cr = vis.reduce((s, a) => s + a.shown[model], 0);
  $('[data-foot]').innerHTML = desk === 'all'
    ? '<b>' + nf.format(D.C) + '</b> subscriptions in ' + D.days + ' days with at least one bylined read. Under every model the 16 authors share exactly ' + nf.format(D.C) + '.'
    : DN[desk] + ' desk: <b>' + cr.toFixed(1) + '</b> of ' + nf.format(D.C) + ' subscriptions credited (' + (cr / D.C * 100).toFixed(1) + '%) under ' + MODELS.find((m) => m.id === model).n.toLowerCase() + '.';
  const dv = conserve(DESKS.map((d) => D.A.filter((a) => a.desk === d.id).reduce((s, a) => s + a.credit[model], 0)), D.C, 1);
  DESKS.forEach((d, i) => { $('[data-dc="' + d.id + '"]').textContent = dv[i]; });
  $('[data-dc="all"]').textContent = D.C;
}
function selectAuthor(id, focusIt) {
  sel = id;
  Object.values(rowNode).forEach((n) => { const on = n.dataset.id === id; n.setAttribute('aria-selected', String(on)); n.tabIndex = on ? 0 : -1; });
  if (focusIt) rowNode[id].focus();
  rowNode[id].scrollIntoView({ block: 'nearest' });
  renderDots(false); renderCard();
}
rowsEl.addEventListener('click', (e) => { const n = e.target.closest('.dmp-bylines__row'); if (n && n.dataset.id !== sel) selectAuthor(n.dataset.id); });
rowsEl.addEventListener('keydown', (e) => {
  const list = $$('.dmp-bylines__row', rowsEl).filter((n) => !n.classList.contains('out')), i = list.findIndex((n) => n.dataset.id === sel);
  let j = -1;
  if (e.key === 'ArrowDown') j = Math.min(list.length - 1, i + 1); else if (e.key === 'ArrowUp') j = Math.max(0, i - 1);
  else if (e.key === 'Home') j = 0; else if (e.key === 'End') j = list.length - 1;
  if (j < 0) return; e.preventDefault(); selectAuthor(list[j].dataset.id, true);
});
$('[data-thead]').addEventListener('click', (e) => {
  const b = e.target.closest('button[data-sort]'); if (!b) return;
  const k = b.dataset.sort; sort = { k, dir: sort.k === k ? -sort.dir : k === 'name' ? 1 : -1 };
  prevRank = null; renderRows(true);
});

/* ------------------------------------------------------------ scatter */
const sc = $('[data-scatter]'), gridG = $('[data-grid]'), dotsG = $('[data-dots]'), tip = $('[data-tip]');
const dotNode = {};
RAW.forEach((a, i) => {
  const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  g.dataset.id = a[0]; g.style.setProperty('--c', deskColor(a[2])); g.style.setProperty('--i', i);
  g.innerHTML = '<circle cx="0" cy="0" r="6"/><text x="0" y="0" text-anchor="middle"></text>';
  g.querySelector('text').textContent = a[1].split(' ')[0];
  dotNode[a[0]] = g; dotsG.appendChild(g);
});
let SG = null;
function median(v) { const s = v.slice().sort((a, b) => a - b), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; }
function renderDots(enter) {
  const W = sc.clientWidth, H = sc.clientHeight; if (!W || !H) return;
  const D = D_(), A = D.A, m = { l: 36, r: 12, t: 24, b: 22 }, iw = W - m.l - m.r, ih = H - m.t - m.b;
  const lx0 = Math.log10(Math.min(...A.map((a) => a.pv)) * 0.8), lx1 = Math.log10(Math.max(...A.map((a) => a.pv)) * 1.15);
  const ymax = Math.max(...PERIODS[period].A.map((a) => Math.max(...MODELS.map((mm) => a.credit[mm.id] / a.pv * 1e5)))) * 1.08;
  const x = (pv) => m.l + (Math.log10(pv) - lx0) / (lx1 - lx0) * iw, y = (v) => m.t + ih - v / ymax * ih;
  const vis = A.filter(visible), mx = median(vis.map((a) => a.pv)), my = median(vis.map(per100k));
  let g = '';
  const step = ymax > 40 ? 10 : ymax > 20 ? 5 : 2;
  for (let v = 0; v <= ymax; v += step) g += '<line x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '"/><text x="' + (m.l - 6) + '" y="' + y(v).toFixed(1) + '" dy="3" text-anchor="end">' + v + '</text>';
  [100000, 200000, 500000, 1000000, 2000000, 5000000].forEach((v) => { if (Math.log10(v) > lx0 && Math.log10(v) < lx1) g += '<text x="' + x(v).toFixed(1) + '" y="' + (H - 6) + '" text-anchor="middle">' + kfmt(v) + '</text>'; });
  g += '<line class="med" x1="' + x(mx).toFixed(1) + '" x2="' + x(mx).toFixed(1) + '" y1="' + m.t + '" y2="' + (m.t + ih) + '"/><line class="med" x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + y(my).toFixed(1) + '" y2="' + y(my).toFixed(1) + '"/>';
  g += '<text class="q" x="' + (W - m.r - 4) + '" y="' + (m.t + 13) + '" text-anchor="end">reach and conversion</text><text class="q" x="' + (m.l + 6) + '" y="' + (m.t + 13) + '">small but converting</text>' +
    '<text class="q" x="' + (W - m.r - 4) + '" y="' + (m.t + ih - 6) + '" text-anchor="end">reach, few subscribers</text><text class="q" x="' + (m.l + 6) + '" y="' + (m.t + ih - 6) + '">room to grow</text>';
  g += '<text class="ax" x="' + (m.l - 30) + '" y="' + (m.t - 12) + '">subscribers per 100k views ↑</text><text class="ax" x="' + (W - m.r) + '" y="' + (H - 6) + '" dy="-12" text-anchor="end">pageviews →</text>';
  gridG.innerHTML = g;
  const top3 = vis.slice().sort((a, b) => b.credit[model] - a.credit[model]).slice(0, 3).map((a) => a.id);
  A.forEach((a) => {
    const n = dotNode[a.id], vx = x(a.pv), vy = y(per100k(a)), r = 3.5 + Math.sqrt(a.stories) * 1.15;
    n.style.transform = 'translate(' + vx.toFixed(1) + 'px,' + vy.toFixed(1) + 'px)';
    n.querySelector('circle').setAttribute('r', r.toFixed(1));
    const t = n.querySelector('text'); t.setAttribute('y', (-r - 5).toFixed(1));
    n.classList.toggle('out', !visible(a));
    n.classList.toggle('lbl', top3.includes(a.id));
    if (a.id === sel) { n.setAttribute('aria-selected', 'true'); if (dotsG.lastElementChild !== n) dotsG.appendChild(n); } else n.removeAttribute('aria-selected');
  });
  dotsG.classList.toggle('enter', !!enter && !RM);
  SG = { x, y };
}
dotsG.addEventListener('click', (e) => { const g = e.target.closest('g[data-id]'); if (g && g.dataset.id !== sel) selectAuthor(g.dataset.id); });
dotsG.addEventListener('pointermove', (e) => {
  const g = e.target.closest('g[data-id]'); if (!g) return;
  const a = au(g.dataset.id), r = sc.getBoundingClientRect();
  tip.innerHTML = '<b>' + a.name + '</b> · ' + DN[a.desk] + '<small>' + a.shown[model].toFixed(1) + ' credited · ' + per100k(a).toFixed(1) + ' per 100k views<br>' + nf.format(a.pv) + ' pageviews · ' + a.stories + ' stories</small>';
  tip.classList.add('on');
  const w = tip.offsetWidth, px = e.clientX - r.left, py = e.clientY - r.top;
  tip.style.left = (px + 14 + w > r.width ? px - w - 14 : px + 14) + 'px'; tip.style.top = Math.max(0, py - 54) + 'px';
});
dotsG.addEventListener('pointerout', (e) => { if (!e.relatedTarget || !dotsG.contains(e.relatedTarget)) tip.classList.remove('on'); });

/* ------------------------------------------------------------ author card */
const card = $('[data-card]');
function renderCard() {
  const a = au(sel), p = a.pos, touches = p.open + p.mid + p.close + p.only, first = a.name.split(' ')[0];
  const segs = [['Opens', p.open, 'var(--dmp-bylines-warm)'], ['Middle', p.mid, 'var(--dmp-bylines-faint)'], ['Closes', p.close, 'var(--dmp-bylines-hi)'], ['Only read', p.only, 'var(--dmp-bylines-business)']];
  const pc = (v) => (touches ? Math.round(v / touches * 100) : 0) + '%';
  const vals = MODELS.map((m) => a.shown[m.id]), lo = Math.min(...vals), hi = Math.max(...vals);
  const role = p.open > p.close * 1.6 ? 'opens journeys' : p.close > p.open * 1.6 ? 'closes them' : 'works both ends';
  const loM = MODELS[vals.indexOf(lo)].n.toLowerCase(), hiM = MODELS[vals.indexOf(hi)].n.toLowerCase();
  card.style.setProperty('--c', deskColor(a.desk));
  card.innerHTML = '<span class="av">' + initials(a.name) + '</span><div class="who"><h4>' + a.name + '</h4><small>' + DN[a.desk] + ' · ' + a.stories + ' stories · best: <q>' + a.best + '</q></small></div>' +
    '<div class="role"><div class="bar">' + segs.map((s) => '<i style="--w:' + s[1] + ';--c:' + s[2] + '"></i>').join('') + '</div><div class="lg">' + segs.map((s) => '<span style="--c:' + s[2] + '">' + s[0] + ' ' + pc(s[1]) + '</span>').join('') + '</div></div>' +
    '<p class="say">' + first + ' <b>' + role + '</b>: of ' + nf.format(touches) + ' reads on paths to a subscription, ' + pc(p.open) + ' were the first and ' + pc(p.close) + ' the last. Credit runs from <b>' + lo.toFixed(1) + '</b> (' + loM + ') to <b>' + hi.toFixed(1) + '</b> (' + hiM + ').</p>' +
    '<div class="models">' + MODELS.map((m) => '<div class="' + (m.id === model ? 'on' : '') + '" style="--v:' + (a.shown[m.id] / hi).toFixed(3) + '">' + m.n + '<b>' + a.shown[m.id].toFixed(1) + '</b><i></i></div>').join('') + '</div>';
}

/* ------------------------------------------------------------ controls */
function radios(group, onPick) {
  const bs = $$('[role="radio"]', group);
  const pick = (b) => { bs.forEach((x) => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; }); onPick(b.dataset.v); };
  group.addEventListener('click', (e) => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  group.addEventListener('keydown', (e) => {
    const i = bs.indexOf(document.activeElement); if (i < 0) return;
    const d = /Right|Down/.test(e.key) ? 1 : /Left|Up/.test(e.key) ? -1 : 0; if (!d) return;
    e.preventDefault(); const b = bs[(i + d + bs.length) % bs.length]; b.focus(); pick(b);
  });
}
radios($('[data-model]'), (v) => { prevRank = ranks(); model = v; renderRows(true); renderDots(false); renderCard(); });
radios($('[data-period]'), (v) => { prevRank = ranks(); period = +v; renderRows(true); renderDots(false); renderCard(); });
radios(desksEl, (v) => {
  desk = v; prevRank = null;
  if (!visible(au(sel))) sel = D_().A.filter(visible).sort((a, b) => b.credit[model] - a.credit[model])[0].id;
  renderRows(true); renderDots(false); renderCard();
});

/* ------------------------------------------------------------ boot */
renderRows(false); renderDots(true); renderCard();
setTimeout(() => { if (!root.isConnected) return; rowsEl.classList.add('settled'); dotsG.classList.remove('enter'); }, 1600);
let rq = 0;
const ro = new ResizeObserver(() => {
  if (rq) return;
  rq = requestAnimationFrame(() => { if (!root.isConnected) { ro.disconnect(); return; } rq = 0; renderDots(false); });
});
ro.observe(sc);
